 86 |     constructor CreateNote(AOwner: TComponent; ANote: TNote; ANoteManager: TNoteManager;
 87 |       AAutosaveService: TAutosaveService; AThemeService: TThemeService; ASettings: TSettings);
 88 |     // Lets an owning form (e.g. TTrayForm) close this note window without
 89 |     // triggering a re-save of a note that's already been deleted/is being
 90 |     // torn down in bulk, without reaching into the private FIsClosing field.
 91 |     procedure CloseWithoutSaving;
 92 |     property Note: TNote read FNote;
 93 |   end;
