110 | constructor TNoteForm.CreateNote(AOwner: TComponent; ANote: TNote; ANoteManager: TNoteManager;
111 |   AAutosaveService: TAutosaveService; AThemeService: TThemeService; ASettings: TSettings);
112 | begin
113 |   inherited Create(AOwner);
114 |   FNote := ANote;
115 |   FNoteManager := ANoteManager;
116 |   FAutosaveService := AAutosaveService;
117 |   FThemeService := AThemeService;
118 |   FSettings := ASettings;
119 |   FCollapsedHeight := COLLAPSED_HEIGHT;
120 |   FIsClosing := False;
121 | end;
