123 | procedure TNoteForm.FormCreate(Sender: TObject);
124 | begin
125 |   TWindowUtils.EnableBorderlessWindow(Self);
126 |   DoubleBuffered := True;
127 |   
128 |   // Header panel setup
129 |   pnlHeader.Height := TWindowUtils.GetCaptionHeight;
130 |   pnlHeader.Align := alTop;
131 |   pnlHeader.BevelOuter := bvNone;
132 |   pnlHeader.ParentBackground := False;
133 |   
134 |   // Buttons
135 |   btnClose.Width := 28;
136 |   btnClose.Height := 28;
137 |   btnClose.Caption := '×';
138 |   btnClose.Font.Size := 16;
139 |   btnClose.Flat := True;
140 |   
141 |   btnColor.Width := 28;
142 |   btnColor.Height := 28;
143 |   btnColor.Caption := '🎨';
144 |   btnColor.Flat := True;
145 |   
146 |   btnPin.Width := 28;
147 |   btnPin.Height := 28;
148 |   btnPin.Caption := '📌';
149 |   btnPin.Flat := True;
150 |   
151 |   btnCollapse.Width := 28;
152 |   btnCollapse.Height := 28;
153 |   btnCollapse.Caption := '□';
154 |   btnCollapse.Flat := True;
155 |   
156 |   btnLock.Width := 28;
157 |   btnLock.Height := 28;
158 |   btnLock.Caption := '🔓';
159 |   btnLock.Flat := True;
160 |   
161 |   // Content memo
162 |   mmContent.Align := alClient;
163 |   mmContent.BorderStyle := bsNone;
164 |   mmContent.ScrollBars := ssVertical;
165 |   mmContent.WordWrap := True;
166 |   mmContent.Font.Name := 'Segoe UI';
167 |   mmContent.Font.Size := 10;
168 |   
169 |   // Popup menu
170 |   miYellow.Tag := Ord(ncYellow);
171 |   miGreen.Tag := Ord(ncGreen);
172 |   miBlue.Tag := Ord(ncBlue);
173 |   miPink.Tag := Ord(ncPink);
174 |   miPurple.Tag := Ord(ncPurple);
175 |   miOrange.Tag := Ord(ncOrange);
176 |   miWhite.Tag := Ord(ncWhite);
177 |   miGray.Tag := Ord(ncGray);
178 |   
179 |   LoadNote;
180 |   ApplyTheme;
181 | end;
