183 | procedure TNoteForm.CloseWithoutSaving;
184 | begin
185 |   FIsClosing := True;
186 |   Close;
187 | end;
188 | 
189 | procedure TNoteForm.FormDestroy(Sender: TObject);
190 | begin
191 |   if not FIsClosing then
192 |     SaveNote;
193 | end;
194 | 
195 | procedure TNoteForm.FormShow(Sender: TObject);
196 | begin
197 |   SetBounds(FNote.Left, FNote.Top, FNote.Width, FNote.Height);
198 |   if FNote.AlwaysOnTop then
199 |     FormStyle := fsStayOnTop;
200 |   if FNote.Collapsed then
201 |   begin
202 |     Height := FCollapsedHeight;
203 |     mmContent.Visible := False;
204 |     btnCollapse.Caption := '▣';
205 |   end;
206 |   UpdateUI;
207 | end;
208 | 
209 | procedure TNoteForm.FormClose(Sender: TObject; var Action: TCloseAction);
210 | begin
211 |   FIsClosing := True;
212 |   SaveNote;
213 |   FAutosaveService.CancelSave;
214 |   Action := caFree;
215 | end;
216 | 
217 | procedure TNoteForm.FormResize(Sender: TObject);
218 | begin
219 |   if not FNote.Collapsed then
220 |   begin
221 |     FNote.Width := Width;
222 |     FNote.Height := Height;
223 |   end;
224 |   FNote.Left := Left;
225 |   FNote.Top := Top;
226 | end;
