228 | procedure TNoteForm.LoadNote;
229 | begin
230 |   Caption := FNote.Title;
231 |   mmContent.Text := FNote.Content;
232 |   Left := FNote.Left;
233 |   Top := FNote.Top;
234 |   Width := FNote.Width;
235 |   Height := FNote.Height;
236 |   ApplyColor;
237 |   UpdateUI;
238 | end;
239 | 
240 | procedure TNoteForm.SaveNote;
241 | begin
242 |   if FNote.Locked then Exit;
243 |   
244 |   FNote.Title := Caption;
245 |   FNote.Content := mmContent.Text;
246 |   FNote.Left := Left;
247 |   FNote.Top := Top;
248 |   if not FNote.Collapsed then
249 |   begin
250 |     FNote.Width := Width;
251 |     FNote.Height := Height;
252 |   end
253 |   else
254 |   begin
255 |     FNote.Width := Width;
256 |     FNote.Height := FCollapsedHeight;
257 |   end;
258 |   
259 |   FNoteManager.SaveNote(FNote);
260 | end;
261 | 
262 | procedure TNoteForm.ApplyColor;
263 | var
264 |   C: TColor;
265 | begin
266 |   C := FThemeService.GetNoteColor(FNote.Color);
267 |   Color := C;
268 |   pnlHeader.Color := TColorUtils.DarkenColor(C, 20);
269 |   mmContent.Color := C;
270 |   mmContent.Font.Color := FThemeService.GetNoteTextColor(FNote.Color);
271 |   
272 |   btnClose.Font.Color := mmContent.Font.Color;
273 |   btnColor.Font.Color := mmContent.Font.Color;
274 |   btnPin.Font.Color := mmContent.Font.Color;
275 |   btnCollapse.Font.Color := mmContent.Font.Color;
276 |   btnLock.Font.Color := mmContent.Font.Color;
277 | end;
278 | 
279 | procedure TNoteForm.UpdateUI;
280 | begin
281 |   btnPin.Enabled := not FNote.Locked;
282 |   btnCollapse.Enabled := not FNote.Locked;
283 |   btnLock.Enabled := True;
284 |   btnColor.Enabled := not FNote.Locked;
285 |   
286 |   miAlwaysOnTop.Checked := FNote.AlwaysOnTop;
287 |   miLock.Checked := FNote.Locked;
288 |   miCollapse.Checked := FNote.Collapsed;
289 |   
290 |   // Update color menu checks
291 |   miYellow.Checked := FNote.Color = ncYellow;
292 |   miGreen.Checked := FNote.Color = ncGreen;
293 |   miBlue.Checked := FNote.Color = ncBlue;
294 |   miPink.Checked := FNote.Color = ncPink;
295 |   miPurple.Checked := FNote.Color = ncPurple;
296 |   miOrange.Checked := FNote.Color = ncOrange;
297 |   miWhite.Checked := FNote.Color = ncWhite;
298 |   miGray.Checked := FNote.Color = ncGray;
299 |   
300 |   if FNote.Locked then
301 |     btnLock.Caption := '🔒'
302 |   else
303 |     btnLock.Caption := '🔓';
304 |     
305 |   if FNote.Collapsed then
306 |     btnCollapse.Caption := '▣'
307 |   else
308 |     btnCollapse.Caption := '□';
309 | end;
310 | 
311 | procedure TNoteForm.ApplyTheme;
312 | begin
313 |   ApplyColor;
314 |   UpdateUI;
315 | end;
