336 | begin
337 |   if FNote.Locked then Exit;
338 |   
339 |   FNote.Collapsed := not FNote.Collapsed;
340 |   if FNote.Collapsed then
341 |   begin
342 |     Height := FCollapsedHeight;
343 |     mmContent.Visible := False;
344 |     btnCollapse.Caption := '▣';
345 |   end
346 |   else
347 |   begin
348 |     Height := FNote.Height;
