388 | procedure TNoteForm.ColorMenuItemClick(Sender: TObject);
389 | var
390 |   Item: TMenuItem;
391 | begin
392 |   if FNote.Locked then Exit;
393 |   
394 |   Item := Sender as TMenuItem;
395 |   FNote.Color := TNoteColor(Item.Tag);
