416 | procedure TNoteForm.miDeleteClick(Sender: TObject);
417 | begin
418 |   if FNote.Locked then Exit;
419 | 
420 |   if (not FSettings.ConfirmDelete) or
421 |      (MessageDlg('Delete this note?', mtConfirmation, [mbYes, mbNo], 0) = mrYes) then
422 |   begin
423 |     FNoteManager.DeleteNote(FNote.ID);
424 |     Close;
425 |   end;
426 | end;
