428 | procedure TNoteForm.miDuplicateClick(Sender: TObject);
429 | var
430 |   NewNote: TNote;
431 | begin
432 |   if FNote.Locked then Exit;
433 |   
434 |   NewNote := FNoteManager.CreateNote(FNote.Title + ' (copy)', FNote.Content, FNote.Color);
435 |   NewNote.Left := FNote.Left + 30;
436 |   NewNote.Top := FNote.Top + 30;
437 |   FNoteManager.SaveNote(NewNote);
438 | end;
