440 | procedure TNoteForm.miPropertiesClick(Sender: TObject);
441 | begin
442 |   // Show properties dialog
443 |   ShowMessage(Format('Note ID: %d'#13#10'Created: %s'#13#10'Modified: %s',
444 |     [FNote.ID, DateTimeToStr(FNote.CreatedAt), DateTimeToStr(FNote.UpdatedAt)]));
445 | end;
