452 | procedure TNoteForm.pnlHeaderMouseDown(Sender: TObject; Button: TMouseButton; Shift: TShiftState; X, Y: Integer);
453 | begin
454 |   if (Button = mbLeft) and (Y < TWindowUtils.GetCaptionHeight) and not FNote.Locked then
455 |   begin
456 |     FDragMode := True;
457 |     FDragOffset := Point(X, Y);
458 |   end;
459 | end;
460 | 
461 | procedure TNoteForm.pnlHeaderMouseMove(Sender: TObject; Shift: TShiftState; X, Y: Integer);
462 | begin
463 |   if FDragMode and (ssLeft in Shift) and not FNote.Locked then
464 |   begin
465 |     Left := Left + (X - FDragOffset.X);
466 |     Top := Top + (Y - FDragOffset.Y);
467 |     FNote.Left := Left;
468 |     FNote.Top := Top;
469 |     FAutosaveService.ScheduleSave(FNote);
470 |   end;
471 | end;
472 | 
473 | procedure TNoteForm.pnlHeaderMouseUp(Sender: TObject; Button: TMouseButton; Shift: TShiftState; X, Y: Integer);
474 | begin
475 |   FDragMode := False;
476 | end;
477 | 
478 | procedure TNoteForm.FormKeyDown(Sender: TObject; var Key: Word; Shift: TShiftState);
479 | begin
480 |   if (Key = VK_F4) and (ssAlt in Shift) then
481 |     Close;
482 | end;
483 | 
484 | procedure TNoteForm.FormMouseWheel(Sender: TObject; Shift: TShiftState; WheelDelta: Integer; MousePos: TPoint; var Handled: Boolean);
485 | begin
486 |   if ssCtrl in Shift then
487 |   begin
488 |     // Ctrl+Wheel to change font size
489 |     mmContent.Font.Size := Max(8, Min(24, mmContent.Font.Size + WheelDelta div 120));
490 |     Handled := True;
491 |   end;
492 | end;
493 | 
494 | procedure TNoteForm.WndProc(var Message: TMessage);
495 | begin
496 |   inherited;
497 |   // Handle any custom messages
498 | end;
499 | 
500 | procedure TNoteForm.WMNCHitTest(var Message: TWMNCHitTest);
501 | begin
502 |   TWindowUtils.HandleNCHitTest(Self, Message);
503 | end;
504 | 
505 | procedure TNoteForm.WMGetMinMaxInfo(var Message: TWMGetMinMaxInfo);
506 | begin
507 |   inherited;
508 |   Message.MinMaxInfo.ptMinTrackSize.X := MIN_WIDTH;
509 |   Message.MinMaxInfo.ptMinTrackSize.Y := MIN_HEIGHT;
510 | end;
511 | 
512 | end.

