 80 | procedure TSettingsForm.FormCreate(Sender: TObject);
 81 | var
 82 |   C: TNoteColor;
 83 | begin
 84 |   // Populate default color combo
 85 |   for C := Low(TNoteColor) to High(TNoteColor) do
 86 |     cbDefaultColor.Items.Add(NoteColorToName(C));
 87 |   cbDefaultColor.Style := csDropDownList;
 88 |   
 89 |   // Setup up/down controls
 90 |   udAutosaveDelay.Min := 100;
 91 |   udAutosaveDelay.Max := 60000;
 92 |   udAutosaveDelay.Increment := 100;
 93 |   
 94 |   udBackupInterval.Min := 1;
 95 |   udBackupInterval.Max := 30;
 96 |   udBackupInterval.Increment := 1;
 97 |   
 98 |   FOriginalSettings := TSettings.Create;
 99 | end;
100 | 
101 | procedure TSettingsForm.FormShow(Sender: TObject);
102 | begin
103 |   LoadControls;
104 | end;
