119 | procedure TSettingsForm.LoadControls;
120 | begin
121 |   if FSettings = nil then Exit;
122 |   
123 |   chkAutoStart.Checked := FSettings.AutoStart;
124 |   chkConfirmDelete.Checked := FSettings.ConfirmDelete;
125 |   edtAutosaveDelay.Text := FSettings.AutosaveDelay.ToString;
126 |   edtDefaultWidth.Text := FSettings.DefaultWidth.ToString;
127 |   edtDefaultHeight.Text := FSettings.DefaultHeight.ToString;
128 |   cbDefaultColor.ItemIndex := Ord(FSettings.DefaultColor);
129 |   chkDefaultAlwaysOnTop.Checked := FSettings.DefaultAlwaysOnTop;
130 |   chkEnableHotkeys.Checked := FSettings.EnableHotkeys;
131 |   chkDarkTheme.Checked := FSettings.DarkTheme;
132 |   edtHotkeyNewNote.Text := FSettings.HotkeyNewNote;
133 |   edtHotkeySearch.Text := FSettings.HotkeySearch;
134 |   chkBackupEnabled.Checked := FSettings.BackupEnabled;
135 |   edtBackupInterval.Text := FSettings.BackupIntervalDays.ToString;
136 | end;
137 | 
138 | procedure TSettingsForm.SaveControls;
139 | begin
140 |   if FSettings = nil then Exit;
141 |   
142 |   FSettings.AutoStart := chkAutoStart.Checked;
143 |   FSettings.ConfirmDelete := chkConfirmDelete.Checked;
144 |   FSettings.AutosaveDelay := StrToIntDef(edtAutosaveDelay.Text, 1000);
145 |   FSettings.DefaultWidth := StrToIntDef(edtDefaultWidth.Text, 300);
146 |   FSettings.DefaultHeight := StrToIntDef(edtDefaultHeight.Text, 250);
147 |   FSettings.DefaultColor := TNoteColor(cbDefaultColor.ItemIndex);
148 |   FSettings.DefaultAlwaysOnTop := chkDefaultAlwaysOnTop.Checked;
149 |   FSettings.EnableHotkeys := chkEnableHotkeys.Checked;
150 |   FSettings.DarkTheme := chkDarkTheme.Checked;
151 |   FSettings.HotkeyNewNote := edtHotkeyNewNote.Text;
152 |   FSettings.HotkeySearch := edtHotkeySearch.Text;
153 |   FSettings.BackupEnabled := chkBackupEnabled.Checked;
154 |   FSettings.BackupIntervalDays := StrToIntDef(edtBackupInterval.Text, 1);
155 | end;
