 88 | procedure TTrayForm.FormCreate(Sender: TObject);
 89 | begin
 90 |   FAppDataPath := GetAppDataPath;
 91 |   FNoteForms := TList<TNoteForm>.Create;
 92 |   
 93 |   // Initialize services
 94 |   FSettings := TSettings.Create;
 95 |   FSettingsController := TSettingsController.Create(TPath.Combine(FAppDataPath, 'settings.ini'));
 96 |   FThemeService := TThemeService.Create;
 97 |   FAutosaveService := TAutosaveService.Create(FSettings.AutosaveDelay);
 98 |   FHotkeyService := THotkeyService.Create(Handle);
 99 |   
100 |   // Initialize storage
101 |   FStorage := TJsonStorage.Create(FAppDataPath);
102 |   
103 |   // Initialize note manager
104 |   FNoteManager := TNoteManager.Create(FStorage);
105 |   FNoteManager.OnNoteCreated := OnNoteCreated;
106 |   FNoteManager.OnNoteChanged := OnNoteChanged;
107 |   FNoteManager.OnNoteDeleted := OnNoteDeleted;
108 |   
109 |   // Initialize tray controller
110 |   FTrayController := TTrayController.Create(FNoteManager, FSettings);
111 |   FTrayController.OnNewNote := OnNewNote;
112 |   FTrayController.OnOpenNotesList := OnOpenNotesList;
113 |   FTrayController.OnSettings := OnSettings;
114 |   FTrayController.OnBackup := OnBackup;
115 |   FTrayController.OnRestore := OnRestore;
116 |   FTrayController.OnAbout := OnAbout;
117 |   FTrayController.OnExit := OnExit;
118 |   
119 |   // Initialize backup service
120 |   FBackupService := TBackupService.Create(FNoteManager, FSettings, TPath.Combine(FAppDataPath, 'backups'));
121 |   
122 |   // Initialize autosave
123 |   FAutosaveService.OnSave := procedure(ANote: TNote)
124 |     begin
125 |       FNoteManager.SaveNote(ANote);
126 |     end;
127 |   
128 |   // Load settings and initialize
129 |   LoadSettings;
130 |   FThemeService.SetDarkTheme(FSettings.DarkTheme);
131 |   FNoteManager.Initialize;
132 |   
133 |   // Setup hotkeys
134 |   if FSettings.EnableHotkeys then
135 |   begin
136 |     FHotkeyService.RegisterHotkey(hkNewNote, FSettings.HotkeyNewNote, OnHotkeyNewNote);
137 |     FHotkeyService.RegisterHotkey(hkSearch, FSettings.HotkeySearch, OnHotkeySearch);
138 |   end;
139 |   
140 |   // Setup tray
141 |   tiMain.Icon := Application.Icon;
142 |   tiMain.Hint := 'Sticky Notes';
143 |   tiMain.Visible := True;
144 |   // NOTE: FTrayController owns its own TTrayIcon/menu, separate from tiMain/pmTray
145 |   // above (wired via the .dfm). Only one tray icon should ever be shown at once,
146 |   // so we deliberately do NOT call FTrayController.ShowTrayIcon here - tiMain is
147 |   // the one the user sees, driven by the miXxxClick handlers below.
148 |   
149 |   // Open existing notes
150 |   OpenAllNotes;
151 |   
152 |   // If no notes, create one
153 |   if FNoteManager.NoteCount = 0 then
154 |     OnNewNote(Self);
155 | end;
