226 | var
227 |   SettingsForm: TSettingsForm;
228 | begin
229 |   SettingsForm := TSettingsForm.Create(Self);
230 |   try
231 |     SettingsForm.LoadSettings(FSettings);
232 |     if SettingsForm.ShowModal = mrOk then
233 |     begin
234 |       SettingsForm.SaveSettings(FSettings);
235 |       SaveSettings;
236 |       FThemeService.SetDarkTheme(FSettings.DarkTheme);
237 |       FAutosaveService.Delay := FSettings.AutosaveDelay;
238 |       
239 |       // Update hotkeys
240 |       if FSettings.EnableHotkeys then
241 |       begin
242 |         FHotkeyService.RegisterHotkey(hkNewNote, FSettings.HotkeyNewNote, OnHotkeyNewNote);
243 |         FHotkeyService.RegisterHotkey(hkSearch, FSettings.HotkeySearch, OnHotkeySearch);
244 |       end
245 |       else
246 |       begin
247 |         FHotkeyService.UnregisterHotkey(hkNewNote);
248 |         FHotkeyService.UnregisterHotkey(hkSearch);
249 |       end;
250 |     end;
251 |   finally
