304 | var
305 |   I: Integer;
306 |   Form: TNoteForm;
307 | begin
308 |   for I := FNoteForms.Count - 1 downto 0 do
309 |   begin
310 |     Form := FNoteForms[I];
311 |     if Form.Note = ANote then
312 |     begin
313 |       Form.CloseWithoutSaving;
314 |       FNoteForms.Delete(I);
315 |       Break;
316 |     end;
317 |   end;
318 | end;
