340 | procedure TTrayForm.OpenAllNotes;
341 | var
342 |   I: Integer;
343 |   Note: TNote;
344 | begin
345 |   for I := 0 to FNoteManager.NoteCount - 1 do
346 |   begin
347 |     Note := FNoteManager.Notes[I];
348 |     // Check if already open
349 |     var Found := False;
350 |     for var Form in FNoteForms do
351 |       if Form.Note = Note then
352 |       begin
353 |         Found := True;
354 |         Break;
355 |       end;
356 |     if not Found then
357 |       CreateNoteForm(Note);
358 |   end;
359 | end;
