 35 |     property DefaultWidth: Integer read FDefaultWidth write FDefaultWidth;
 36 |     property DefaultHeight: Integer read FDefaultHeight write FDefaultHeight;
 37 |     property DefaultAlwaysOnTop: Boolean read FDefaultAlwaysOnTop write FDefaultAlwaysOnTop;
 38 |     property EnableHotkeys: Boolean read FEnableHotkeys write FEnableHotkeys;
 39 |     property BackupEnabled: Boolean read FBackupEnabled write FBackupEnabled;
 40 |     property BackupIntervalDays: Integer read FBackupIntervalDays write FBackupIntervalDays;
 41 |     property DarkTheme: Boolean read FDarkTheme write FDarkTheme;
 42 |     property HotkeyNewNote: string read FHotkeyNewNote write FHotkeyNewNote;
 43 |     property HotkeySearch: string read FHotkeySearch write FHotkeySearch;
 44 |   end;
 45 | 
 46 | implementation
 47 | 
 48 | { TSettings }
 49 | 
 50 | constructor TSettings.Create;
 51 | begin
 52 |   inherited;
 53 |   SetDefaults;
 54 | end;
 55 | 
 56 | procedure TSettings.SetDefaults;
 57 | begin
 58 |   FAutoStart := False;
 59 |   FConfirmDelete := True;
 60 |   FAutosaveDelay := 1000; // 1 second
 61 |   FDefaultColor := ncYellow;
 62 |   FDefaultWidth := 300;
 63 |   FDefaultHeight := 250;
 64 |   FDefaultAlwaysOnTop := False;
 65 |   FEnableHotkeys := True;
 66 |   FBackupEnabled := True;
 67 |   FBackupIntervalDays := 1;
 68 |   FDarkTheme := False;
 69 |   FHotkeyNewNote := 'Ctrl+Alt+N';
 70 |   FHotkeySearch := 'Ctrl+Alt+F';
 71 | end;
 72 | 
 73 | procedure TSettings.LoadFromFile(const AFileName: string);
 74 | var
 75 |   Ini: TIniFile;
 76 | begin
 77 |   SetDefaults;
 78 |   if not FileExists(AFileName) then Exit;
 79 |   Ini := TIniFile.Create(AFileName);
 80 |   try
 81 |     FAutoStart := Ini.ReadBool('General', 'AutoStart', FAutoStart);
 82 |     FConfirmDelete := Ini.ReadBool('General', 'ConfirmDelete', FConfirmDelete);
 83 |     FAutosaveDelay := Ini.ReadInteger('General', 'AutosaveDelay', FAutosaveDelay);
 84 |     FDefaultColor := TNoteColor(Ini.ReadInteger('General', 'DefaultColor', Ord(FDefaultColor)));
 85 |     FDefaultWidth := Ini.ReadInteger('General', 'DefaultWidth', FDefaultWidth);
 86 |     FDefaultHeight := Ini.ReadInteger('General', 'DefaultHeight', FDefaultHeight);
 87 |     FDefaultAlwaysOnTop := Ini.ReadBool('General', 'DefaultAlwaysOnTop', FDefaultAlwaysOnTop);
 88 |     FEnableHotkeys := Ini.ReadBool('General', 'EnableHotkeys', FEnableHotkeys);
 89 |     FBackupEnabled := Ini.ReadBool('Backup', 'Enabled', FBackupEnabled);
 90 |     FBackupIntervalDays := Ini.ReadInteger('Backup', 'IntervalDays', FBackupIntervalDays);
 91 |     FDarkTheme := Ini.ReadBool('Appearance', 'DarkTheme', FDarkTheme);
 92 |     FHotkeyNewNote := Ini.ReadString('Hotkeys', 'NewNote', FHotkeyNewNote);
 93 |     FHotkeySearch := Ini.ReadString('Hotkeys', 'Search', FHotkeySearch);
 94 |   finally
 95 |     Ini.Free;
 96 |   end;
 97 | end;
 98 | 
 99 | procedure TSettings.SaveToFile(const AFileName: string);
100 | var
101 |   Ini: TIniFile;
102 | begin
103 |   Ini := TIniFile.Create(AFileName);
104 |   try
105 |     Ini.WriteBool('General', 'AutoStart', FAutoStart);
106 |     Ini.WriteBool('General', 'ConfirmDelete', FConfirmDelete);
107 |     Ini.WriteInteger('General', 'AutosaveDelay', FAutosaveDelay);
108 |     Ini.WriteInteger('General', 'DefaultColor', Ord(FDefaultColor));
109 |     Ini.WriteInteger('General', 'DefaultWidth', FDefaultWidth);
110 |     Ini.WriteInteger('General', 'DefaultHeight', FDefaultHeight);
111 |     Ini.WriteBool('General', 'DefaultAlwaysOnTop', FDefaultAlwaysOnTop);
112 |     Ini.WriteBool('General', 'EnableHotkeys', FEnableHotkeys);
113 |     Ini.WriteBool('Backup', 'Enabled', FBackupEnabled);
114 |     Ini.WriteInteger('Backup', 'IntervalDays', FBackupIntervalDays);
115 |     Ini.WriteBool('Appearance', 'DarkTheme', FDarkTheme);
116 |     Ini.WriteString('Hotkeys', 'NewNote', FHotkeyNewNote);
117 |     Ini.WriteString('Hotkeys', 'Search', FHotkeySearch);
118 |   finally
119 |     Ini.Free;
120 |   end;
121 | end;
122 | 
123 | procedure TSettings.Assign(Source: TSettings);
124 | begin
125 |   if Source = nil then Exit;
126 |   FAutoStart := Source.FAutoStart;
127 |   FConfirmDelete := Source.FConfirmDelete;
128 |   FAutosaveDelay := Source.FAutosaveDelay;
129 |   FDefaultColor := Source.FDefaultColor;
130 |   FDefaultWidth := Source.FDefaultWidth;
131 |   FDefaultHeight := Source.FDefaultHeight;
132 |   FDefaultAlwaysOnTop := Source.FDefaultAlwaysOnTop;
133 |   FEnableHotkeys := Source.FEnableHotkeys;
134 |   FBackupEnabled := Source.FBackupEnabled;
135 |   FBackupIntervalDays := Source.FBackupIntervalDays;
136 |   FDarkTheme := Source.FDarkTheme;
137 |   FHotkeyNewNote := Source.FHotkeyNewNote;
138 |   FHotkeySearch := Source.FHotkeySearch;
139 | end;
140 | 
141 | end.

 1 | unit uEnums;
 2 | 
 3 | interface
 4 | 
 5 | uses
 6 |   System.SysUtils, System.UITypes;
 7 | 
 8 | type
 9 |   TNoteColor = (
10 |     ncYellow,
11 |     ncGreen,
12 |     ncBlue,
13 |     ncPink,
14 |     ncPurple,
15 |     ncOrange,
16 |     ncWhite,
17 |     ncGray
18 |   );
19 | 
20 |   TStorageType = (
21 |     stJson,
22 |     stSQLite,
23 |     stCloud
24 |   );
25 | 
26 | const
27 |   NOTE_COLOR_VALUES: array[TNoteColor] of TColor = (
28 |     $0080FFFF, // Yellow (BGR: $FFFF80)
29 |     $0080FF80, // Green (BGR: $80FF80)
30 |     $00FFC080, // Blue (BGR: $80C0FF)
31 |     $00C080FF, // Pink (BGR: $FF80C0)
32 |     $00FF80FF, // Purple (BGR: $FF80FF)
33 |     $0080C0FF, // Orange (BGR: $FFC080)
34 |     $00FFFFFF, // White
35 |     $00E0E0E0  // Gray
36 |   );
37 | 
38 |   NOTE_COLOR_NAMES: array[TNoteColor] of string = (
39 |     'Yellow',
40 |     'Green',
41 |     'Blue',
42 |     'Pink',
43 |     'Purple',
44 |     'Orange',
45 |     'White',
46 |     'Gray'
47 |   );
48 | 
49 | function ColorToNoteColor(AColor: TColor): TNoteColor;
50 | function NoteColorToColor(ANoteColor: TNoteColor): TColor;
51 | function NoteColorToName(ANoteColor: TNoteColor): string;
52 | function NoteColorFromName(const AName: string): TNoteColor;
53 | 
54 | implementation
55 | 
56 | function ColorToNoteColor(AColor: TColor): TNoteColor;
57 | var
58 |   C: TNoteColor;
59 | begin
60 |   Result := ncYellow;
61 |   for C := Low(TNoteColor) to High(TNoteColor) do
62 |     if NOTE_COLOR_VALUES[C] = AColor then
63 |       Exit(C);
64 | end;
65 | 
66 | function NoteColorToColor(ANoteColor: TNoteColor): TColor;
67 | begin
68 |   Result := NOTE_COLOR_VALUES[ANoteColor];
69 | end;
70 | 
71 | function NoteColorToName(ANoteColor: TNoteColor): string;
72 | begin
73 |   Result := NOTE_COLOR_NAMES[ANoteColor];
74 | end;
75 | 
76 | function NoteColorFromName(const AName: string): TNoteColor;
77 | var
78 |   C: TNoteColor;
79 | begin
80 |   Result := ncYellow;
81 |   for C := Low(TNoteColor) to High(TNoteColor) do
82 |     if SameText(NOTE_COLOR_NAMES[C], AName) then
83 |       Exit(C);
84 | end;
85 | 
86 | end.

  1 | unit uNoteManager;
  2 | 
  3 | interface
  4 | 
  5 | uses
  6 |   System.SysUtils, System.Classes, System.Generics.Collections,
  7 |   uNote, uStorage, uEnums;
  8 | 
  9 | type
 10 |   TNoteEvent = procedure(const ANote: TNote) of object;
 11 | 
 12 |   TNoteManager = class
 13 |   private
 14 |     FStorage: INoteStorage;
 15 |     FNotes: TObjectList<TNote>;
 16 |     FOnNoteCreated: TNoteEvent;
 17 |     FOnNoteChanged: TNoteEvent;
 18 |     FOnNoteDeleted: TNoteEvent;
 19 |     function GetNoteCount: Integer;
 20 |     function GetNote(Index: Integer): TNote;
 21 |   public
 22 |     constructor Create(const AStorage: INoteStorage);
 23 |     destructor Destroy; override;
 24 |     procedure Initialize;
 25 |     procedure Finalize;
 26 |     function CreateNote(const ATitle, AContent: string; AColor: TNoteColor = ncYellow): TNote;
 27 |     function AddNote(ANote: TNote): Boolean;
 28 |     function DeleteNote(const ANoteID: Int64): Boolean;
 29 |     function FindByID(const ANoteID: Int64): TNote;
 30 |     function FindByIndex(const AIndex: Integer): TNote;
 31 |     procedure SaveNote(const ANote: TNote);
 32 |     procedure LoadNotes;
 33 |     procedure OpenAllNotes;
 34 |     procedure CloseAllNotes;
 35 |     property NoteCount: Integer read GetNoteCount;
 36 |     property Notes[Index: Integer]: TNote read GetNote; default;
 37 |     property OnNoteCreated: TNoteEvent read FOnNoteCreated write FOnNoteCreated;
 38 |     property OnNoteChanged: TNoteEvent read FOnNoteChanged write FOnNoteChanged;
 39 |     property OnNoteDeleted: TNoteEvent read FOnNoteDeleted write FOnNoteDeleted;
 40 |   end;
 41 | 
 42 | implementation
 43 | 
 44 | { TNoteManager }
 45 | 
 46 | constructor TNoteManager.Create(const AStorage: INoteStorage);
 47 | begin
 48 |   inherited Create;
 49 |   FStorage := AStorage;
 50 |   FNotes := TObjectList<TNote>.Create(True);
 51 | end;
 52 | 
 53 | destructor TNoteManager.Destroy;
 54 | begin
 55 |   Finalize;
 56 |   FNotes.Free;
 57 |   inherited;
 58 | end;
 59 | 
 60 | procedure TNoteManager.Initialize;
 61 | begin
 62 |   FStorage.Initialize;
 63 |   LoadNotes;
 64 | end;
 65 | 
 66 | procedure TNoteManager.Finalize;
 67 | begin
 68 |   FStorage.Finalize;
 69 |   FNotes.Clear;
 70 | end;
 71 | 
 72 | function TNoteManager.GetNoteCount: Integer;
 73 | begin
 74 |   Result := FNotes.Count;
 75 | end;
 76 | 
 77 | function TNoteManager.GetNote(Index: Integer): TNote;
 78 | begin
 79 |   if (Index >= 0) and (Index < FNotes.Count) then
 80 |     Result := FNotes[Index]
 81 |   else
 82 |     Result := nil;
 83 | end;
 84 | 
 85 | function TNoteManager.CreateNote(const ATitle, AContent: string; AColor: TNoteColor = ncYellow): TNote;
 86 | begin
 87 |   Result := TNote.Create(FStorage.GetNextID, ATitle, AContent, AColor);
 88 |   FNotes.Add(Result);
 89 |   SaveNote(Result);
 90 |   if Assigned(FOnNoteCreated) then
 91 |     FOnNoteCreated(Result);
 92 | end;
 93 | 
 94 | function TNoteManager.AddNote(ANote: TNote): Boolean;
 95 | begin
 96 |   // Public way to import/restore an existing TNote instance without callers
 97 |   // reaching into the private FNotes list directly (e.g. from TBackupService).
 98 |   Result := False;
 99 |   if ANote = nil then Exit;
100 |   if FindByID(ANote.ID) <> nil then Exit; // already present, caller should free it
101 | 
102 |   FNotes.Add(ANote);
103 |   SaveNote(ANote); // persists via storage and fires OnNoteChanged
104 |   if Assigned(FOnNoteCreated) then
105 |     FOnNoteCreated(ANote);
106 |   Result := True;
107 | end;
108 | 
109 | function TNoteManager.DeleteNote(const ANoteID: Int64): Boolean;
110 | var
111 |   Note: TNote;
112 |   Index: Integer;
113 | begin
114 |   Result := False;
115 |   Note := FindByID(ANoteID);
116 |   if Note = nil then Exit;
117 |   
118 |   Index := FNotes.IndexOf(Note);
119 |   if Index < 0 then Exit;
120 |   
121 |   if FStorage.DeleteNote(ANoteID) then
122 |   begin
123 |     FNotes.Delete(Index);
124 |     if Assigned(FOnNoteDeleted) then
125 |       FOnNoteDeleted(Note);
126 |     Result := True;
127 |   end;
128 | end;
129 | 
130 | function TNoteManager.FindByID(const ANoteID: Int64): TNote;
131 | var
132 |   Note: TNote;
133 | begin
134 |   Result := nil;
135 |   for Note in FNotes do
136 |     if Note.ID = ANoteID then
137 |       Exit(Note);
138 | end;
139 | 
140 | function TNoteManager.FindByIndex(const AIndex: Integer): TNote;
141 | begin
142 |   if (AIndex >= 0) and (AIndex < FNotes.Count) then
143 |     Result := FNotes[AIndex]
144 |   else
145 |     Result := nil;
146 | end;
147 | 
148 | procedure TNoteManager.SaveNote(const ANote: TNote);
149 | begin
150 |   if FStorage.SaveNote(ANote) then
151 |   begin
152 |     ANote.Touch;
153 |     if Assigned(FOnNoteChanged) then
154 |       FOnNoteChanged(ANote);
155 |   end;
156 | end;
157 | 
158 | procedure TNoteManager.LoadNotes;
159 | var
160 |   LoadedNotes: TObjectList<TNote>;
161 |   Note: TNote;
162 | begin
163 |   FNotes.Clear;
164 |   LoadedNotes := FStorage.LoadAllNotes;
165 |   try
166 |     for Note in LoadedNotes do
167 |       FNotes.Add(Note);
168 |     LoadedNotes.OwnsObjects := False; // Don't free notes, we own them now
169 |   finally
170 |     LoadedNotes.Free;
171 |   end;
172 | end;
173 | 
174 | procedure TNoteManager.OpenAllNotes;
175 | var
176 |   Note: TNote;
177 | begin
178 |   // This will be implemented when forms are created
179 |   // For now, just a placeholder for the controller to use
180 |   for Note in FNotes do
181 |   begin
182 |     // Open note form for each note
183 |   end;
184 | end;
185 | 
186 | procedure TNoteManager.CloseAllNotes;
187 | begin
188 |   // Close all open note forms
189 |   // Implemented in controller
190 | end;
191 | 
192 | end.

