 97 |   Item.OnClick := OnMenuItemClick;
 98 |   Item.Tag := 4;
 99 |   FPopupMenu.Items.Add(Item);
100 | 
101 |   // Restore
102 |   Item := TMenuItem.Create(FPopupMenu);
103 |   Item.Caption := '&Restore...';
104 |   Item.OnClick := OnMenuItemClick;
105 |   Item.Tag := 5;
106 |   FPopupMenu.Items.Add(Item);
107 | 
108 |   FPopupMenu.Items.Add(TMenuItem.Create(FPopupMenu)); // Separator
109 | 
