 1 | unit uAutosaveService;
 2 | 
 3 | interface
 4 | 
 5 | uses
 6 |   System.SysUtils, System.Classes, Vcl.ExtCtrls,
 7 |   uNote;
 8 | 
 9 | type
10 |   TAutosaveService = class
11 |   private
12 |     FTimer: TTimer;
13 |     FDelay: Integer;
14 |     FOnSave: TProc<TNote>;
15 |     FPendingNote: TNote;
16 |     procedure OnTimer(Sender: TObject);
17 |   public
18 |     constructor Create(ADelay: Integer = 1000);
19 |     destructor Destroy; override;
20 |     procedure ScheduleSave(ANote: TNote);
21 |     procedure CancelSave;
22 |     procedure Flush;
23 |     property OnSave: TProc<TNote> read FOnSave write FOnSave;
24 |     property Delay: Integer read FDelay write FDelay;
25 |   end;
26 | 
27 | implementation
28 | 
29 | { TAutosaveService }
30 | 
31 | constructor TAutosaveService.Create(ADelay: Integer = 1000);
32 | begin
33 |   inherited Create;
34 |   FDelay := ADelay;
35 |   FTimer := TTimer.Create(nil);
36 |   FTimer.Enabled := False;
37 |   FTimer.Interval := FDelay;
38 |   FTimer.OnTimer := OnTimer;
39 | end;
40 | 
41 | destructor TAutosaveService.Destroy;
42 | begin
43 |   FTimer.Free;
44 |   inherited;
45 | end;
46 | 
47 | procedure TAutosaveService.OnTimer(Sender: TObject);
48 | begin
49 |   FTimer.Enabled := False;
50 |   if Assigned(FPendingNote) and Assigned(FOnSave) then
51 |     FOnSave(FPendingNote);
52 |   FPendingNote := nil;
53 | end;
54 | 
55 | procedure TAutosaveService.ScheduleSave(ANote: TNote);
56 | begin
57 |   FPendingNote := ANote;
58 |   FTimer.Enabled := False;
59 |   FTimer.Interval := FDelay;
60 |   FTimer.Enabled := True;
61 | end;
62 | 
63 | procedure TAutosaveService.CancelSave;
64 | begin
65 |   FTimer.Enabled := False;
66 |   FPendingNote := nil;
67 | end;
68 | 
69 | procedure TAutosaveService.Flush;
70 | begin
71 |   if FTimer.Enabled and Assigned(FPendingNote) and Assigned(FOnSave) then
72 |   begin
73 |     FTimer.Enabled := False;
74 |     FOnSave(FPendingNote);
75 |     FPendingNote := nil;
76 |   end;
77 | end;
78 | 
79 | end.

