  9 | type
 10 |   TBackupProgress = procedure(const AMessage: string; AProgress: Integer) of object;
 11 |   TBackupComplete = procedure(ASuccess: Boolean; const AMessage: string) of object;
 12 | 
 13 |   TBackupService = class
 14 |   private
 15 |     FNoteManager: TNoteManager;
 16 |     FSettings: TSettings;
 17 |     FBackupPath: string;
 18 |     FOnProgress: TBackupProgress;
 19 |     FOnComplete: TBackupComplete;
 20 |     function GetBackupFileName: string;
 21 |     function CreateBackupZip(const AZipFile: string): Boolean;
 22 |   public
 23 |     constructor Create(ANoteManager: TNoteManager; ASettings: TSettings; const ABackupPath: string);
 24 |     destructor Destroy; override;
 25 |     procedure Backup;
 26 |     procedure Restore(const ABackupFile: string);
 27 |     property OnProgress: TBackupProgress read FOnProgress write FOnProgress;
 28 |     property OnComplete: TBackupComplete read FOnComplete write FOnComplete;
 29 |   end;
 30 | 
 31 | implementation
 32 | 
 33 | uses
 34 |   System.Types, System.JSON, uNote, uEnums;
 35 | 
 36 | function GetRelativePath(const ABasePath, AFileName: string): string;
 37 | var
 38 |   BasePath, FilePath: string;
 39 | begin
 40 |   BasePath := IncludeTrailingPathDelimiter(ExpandFileName(ABasePath));
 41 |   FilePath := ExpandFileName(AFileName);
 42 |   if SameText(Copy(FilePath, 1, Length(BasePath)), BasePath) then
 43 |     Result := Copy(FilePath, Length(BasePath) + 1, MaxInt)
 44 |   else
 45 |     Result := FilePath;
 46 | end;
 47 | 
 48 | function DateTimeToISO8601(const ADateTime: TDateTime): string;
 49 | begin
 50 |   Result := FormatDateTime('yyyy-mm-dd"T"hh:nn:ss', ADateTime);
 51 | end;
 52 | 
 53 | { TBackupService }
 54 | 
 55 | constructor TBackupService.Create(ANoteManager: TNoteManager; ASettings: TSettings; const ABackupPath: string);
 56 | begin
 57 |   inherited Create;
 58 |   FNoteManager := ANoteManager;
 59 |   FSettings := ASettings;
 60 |   FBackupPath := ABackupPath;
 61 |   if not TDirectory.Exists(FBackupPath) then
 62 |     TDirectory.CreateDirectory(FBackupPath);
 63 | end;
 64 | 
 65 | destructor TBackupService.Destroy;
 66 | begin
 67 |   inherited;
 68 | end;
