 70 | function TBackupService.GetBackupFileName: string;
 71 | var
 72 |   DateStr: string;
 73 | begin
 74 |   DateStr := FormatDateTime('yyyymmdd_hhnnss', Now);
 75 |   Result := TPath.Combine(FBackupPath, 'StickyNotes_Backup_' + DateStr + '.zip');
 76 | end;
