 78 | procedure TBackupService.Backup;
 79 | var
 80 |   ZipFile: string;
 81 |   Success: Boolean;
 82 | begin
 83 |   if Assigned(FOnProgress) then
 84 |     FOnProgress('Creating backup...', 0);
 85 |   
 86 |   ZipFile := GetBackupFileName;
 87 |   Success := CreateBackupZip(ZipFile);
 88 |   
 89 |   if Assigned(FOnComplete) then
 90 |   begin
 91 |     if Success then
 92 |       FOnComplete(True, 'Backup created: ' + TPath.GetFileName(ZipFile))
 93 |     else
 94 |       FOnComplete(False, 'Backup failed');
