 98 | function TBackupService.CreateBackupZip(const AZipFile: string): Boolean;
 99 | var
100 |   Zip: TZipFile;
101 |   NotesPath: string;
102 |   Files: TStringDynArray;
103 |   FileName: string;
104 |   RelPath: string;
105 |   SettingsFile: string;
106 |   Note: TNote;
107 |   JsonText: string;
108 |   Json: System.JSON.TJSONObject;
109 |   TempDir: string;
110 |   Stream: TStringStream;
111 |   I: Integer;
112 | begin
113 |   Result := False;
114 |   TempDir := TPath.Combine(TPath.GetTempPath, 'StickyNotes_Backup_' + FormatDateTime('yyyymmdd_hhnnss', Now));
115 |   
116 |   try
117 |     TDirectory.CreateDirectory(TempDir);
118 |     
119 |     // Export notes as JSON files
120 |     NotesPath := TPath.Combine(TempDir, 'notes');
121 |     TDirectory.CreateDirectory(NotesPath);
122 |     
123 |     if Assigned(FOnProgress) then
124 |       FOnProgress('Exporting notes...', 20);
125 |     
126 |     for I := 0 to FNoteManager.NoteCount - 1 do
127 |     begin
128 |       Note := FNoteManager.Notes[I];
129 |       Json := System.JSON.TJSONObject.Create;
130 |       try
131 |         Json.AddPair('ID', System.JSON.TJSONNumber.Create(Note.ID));
132 |         Json.AddPair('Title', Note.Title);
133 |         Json.AddPair('Content', Note.Content);
134 |         Json.AddPair('Color', Ord(Note.Color));
135 |         Json.AddPair('Left', Note.Left);
136 |         Json.AddPair('Top', Note.Top);
137 |         Json.AddPair('Width', Note.Width);
138 |         Json.AddPair('Height', Note.Height);
139 |         Json.AddPair('AlwaysOnTop', Note.AlwaysOnTop);
140 |         Json.AddPair('Collapsed', Note.Collapsed);
141 |         Json.AddPair('Locked', Note.Locked);
142 |         Json.AddPair('CreatedAt', DateTimeToISO8601(Note.CreatedAt));
143 |         Json.AddPair('UpdatedAt', DateTimeToISO8601(Note.UpdatedAt));
144 |         
145 |         JsonText := Json.Format;
146 |         FileName := TPath.Combine(NotesPath, Format('%.10d.json', [Note.ID]));
147 |         TFile.WriteAllText(FileName, JsonText, TEncoding.UTF8);
148 |       finally
149 |         Json.Free;
150 |       end;
151 |     end;
152 |     
153 |     // Export settings
154 |     if Assigned(FOnProgress) then
155 |       FOnProgress('Exporting settings...', 60);
156 |     
157 |     SettingsFile := TPath.Combine(TempDir, 'settings.ini');
158 |     FSettings.SaveToFile(SettingsFile);
159 |     
160 |     // Create ZIP
161 |     if Assigned(FOnProgress) then
162 |       FOnProgress('Creating archive...', 80);
163 |     
164 |     Zip := TZipFile.Create;
165 |     try
166 |       Zip.Open(AZipFile, zmWrite);
167 |       try
168 |         Files := TDirectory.GetFiles(TempDir, '*.*', TSearchOption.soAllDirectories);
169 |         for FileName in Files do
170 |         begin
171 |           RelPath := GetRelativePath(TempDir, FileName);
172 |           Zip.Add(FileName, RelPath);
173 |         end;
174 |       finally
175 |         Zip.Close;
176 |       end;
177 |       Result := True;
178 |     finally
179 |       Zip.Free;
180 |     end;
181 |     
182 |     if Assigned(FOnProgress) then
183 |       FOnProgress('Complete', 100);
184 |     
185 |   finally
186 |     // Cleanup temp directory
187 |     if TDirectory.Exists(TempDir) then
188 |       TDirectory.Delete(TempDir, True);
189 |   end;
190 | end;
191 | 
192 | procedure TBackupService.Restore(const ABackupFile: string);
193 | var
194 |   Zip: TZipFile;
195 |   TempDir: string;
196 |   Files: TStringDynArray;
197 |   FileName: string;
198 |   RelPath: string;
199 |   ExtractPath: string;
200 |   JsonText: string;
201 |   Json: System.JSON.TJSONObject;
202 |   Note: TNote;
203 |   ColorInt: Integer;
204 |   CreatedStr, UpdatedStr: string;
205 |   SettingsFile: string;
206 | begin
207 |   if Assigned(FOnProgress) then
208 |     FOnProgress('Extracting backup...', 0);
209 |   
210 |   TempDir := TPath.Combine(TPath.GetTempPath, 'StickyNotes_Restore_' + FormatDateTime('yyyymmdd_hhnnss', Now));
211 |   
212 |   try
213 |     TDirectory.CreateDirectory(TempDir);
214 |     
215 |     Zip := TZipFile.Create;
216 |     try
217 |       Zip.Open(ABackupFile, zmRead);
218 |       try
219 |         Zip.ExtractAll(TempDir);
220 |       finally
221 |         Zip.Close;
222 |       end;
223 |     finally
224 |       Zip.Free;
225 |     end;
226 |     
227 |     if Assigned(FOnProgress) then
228 |       FOnProgress('Restoring notes...', 40);
229 |     
230 |     // Restore notes
231 |     ExtractPath := TPath.Combine(TempDir, 'notes');
232 |     if TDirectory.Exists(ExtractPath) then
233 |     begin
234 |       Files := TDirectory.GetFiles(ExtractPath, '*.json');
235 |       for FileName in Files do
236 |       begin
237 |         try
238 |           JsonText := TFile.ReadAllText(FileName, TEncoding.UTF8);
239 |           Json := System.JSON.TJSONObject.ParseJSONValue(JsonText) as System.JSON.TJSONObject;
240 |           if Json <> nil then
241 |           try
242 |             Note := TNote.Create;
243 |             Note.ID := Json.GetValue<Int64>('ID', 0);
244 |             Note.Title := Json.GetValue<string>('Title', '');
245 |             Note.Content := Json.GetValue<string>('Content', '');
246 |             ColorInt := Json.GetValue<Integer>('Color', Ord(ncYellow));
247 |             Note.Color := TNoteColor(ColorInt);
248 |             Note.Left := Json.GetValue<Integer>('Left', 100);
249 |             Note.Top := Json.GetValue<Integer>('Top', 100);
250 |             Note.Width := Json.GetValue<Integer>('Width', 300);
251 |             Note.Height := Json.GetValue<Integer>('Height', 250);
252 |             Note.AlwaysOnTop := Json.GetValue<Boolean>('AlwaysOnTop', False);
253 |             Note.Collapsed := Json.GetValue<Boolean>('Collapsed', False);
254 |             Note.Locked := Json.GetValue<Boolean>('Locked', False);
255 |             CreatedStr := Json.GetValue<string>('CreatedAt', '');
256 |             UpdatedStr := Json.GetValue<string>('UpdatedAt', '');
257 |             if CreatedStr <> '' then
258 |               Note.CreatedAt := ISO8601ToDate(CreatedStr)
259 |             else
260 |               Note.CreatedAt := Now;
261 |             if UpdatedStr <> '' then
262 |               Note.UpdatedAt := ISO8601ToDate(UpdatedStr)
263 |             else
264 |               Note.UpdatedAt := Now;
265 |             
266 |             // AddNote checks for an existing ID itself, persists the note via
267 |             // storage, and fires OnNoteCreated so a note window actually opens.
268 |             if not FNoteManager.AddNote(Note) then
269 |               Note.Free;
270 |           finally
271 |             Json.Free;
272 |           end;
273 |         except
274 |           // Skip corrupted files
275 |         end;
276 |       end;
277 |     end;
278 |     
279 |     // Restore settings
280 |     if Assigned(FOnProgress) then
281 |       FOnProgress('Restoring settings...', 80);
282 |     
283 |     SettingsFile := TPath.Combine(TempDir, 'settings.ini');
284 |     if TFile.Exists(SettingsFile) then
285 |       FSettings.LoadFromFile(SettingsFile);
286 |     
287 |     if Assigned(FOnComplete) then
288 |       FOnComplete(True, 'Restore complete');
289 |     
290 |   except
291 |     on E: Exception do
292 |       if Assigned(FOnComplete) then
293 |         FOnComplete(False, 'Restore failed: ' + E.Message);
294 |   end;
295 |   
296 |   // Cleanup
297 |   if TDirectory.Exists(TempDir) then
298 |     TDirectory.Delete(TempDir, True);
299 | end;
300 | 
301 | end.

  1 | unit uHotkeyService;
  2 | 
  3 | interface
  4 | 
  5 | uses
  6 |   System.SysUtils, System.Classes, System.Types, Winapi.Windows, Winapi.Messages,
  7 |   Vcl.Forms;
  8 | 
  9 | type
 10 |   THotkeyID = (hkNewNote, hkSearch, hkCustom1, hkCustom2, hkCustom3);
 11 |   THotkeyEvent = procedure of object;
 12 | 
 13 |   THotkeyService = class
 14 |   private
 15 |     FHandle: HWND;
 16 |     FRegistered: array[THotkeyID] of Boolean;
 17 |     FHotkeys: array[THotkeyID] of record
 18 |       Modifiers: UINT;
 19 |       Key: UINT;
 20 |       Enabled: Boolean;
 21 |       Event: THotkeyEvent;
 22 |       HotkeyStr: string; // kept so EnableHotkey(True) can re-register later
 23 |     end;
 24 |     FOnHotkey: array[THotkeyID] of THotkeyEvent;
 25 |     procedure WndProc(var Message: TMessage);
 26 |     function ParseHotkey(const AHotkeyStr: string; out AModifiers, AKey: UINT): Boolean;
 27 |   public
 28 |     constructor Create(AHandle: HWND);
 29 |     destructor Destroy; override;
 30 |     function RegisterHotkey(AID: THotkeyID; const AHotkeyStr: string; AEvent: THotkeyEvent): Boolean;
 31 |     function UnregisterHotkey(AID: THotkeyID): Boolean;
 32 |     procedure SetHotkey(AID: THotkeyID; const AHotkeyStr: string; AEvent: THotkeyEvent);
 33 |     procedure EnableHotkey(AID: THotkeyID; AEnable: Boolean);
 34 |     procedure UpdateFromSettings;
 35 |   end;
 36 | 
 37 | implementation
 38 | 
 39 | uses
 40 |   uSettings;
 41 | 
 42 | const
 43 |   HOTKEY_MSG = WM_HOTKEY;
 44 |   BASE_HOTKEY_ID = $8000;
 45 | 
 46 | { THotkeyService }
 47 | 
 48 | constructor THotkeyService.Create(AHandle: HWND);
 49 | var
 50 |   ID: THotkeyID;
 51 | begin
 52 |   inherited Create;
 53 |   FHandle := AHandle;
 54 |   for ID := Low(THotkeyID) to High(THotkeyID) do
 55 |   begin
 56 |     FRegistered[ID] := False;
 57 |     FHotkeys[ID].Enabled := False;
 58 |     FHotkeys[ID].Event := nil;
 59 |   end;
 60 | end;
 61 | 
 62 | destructor THotkeyService.Destroy;
 63 | var
 64 |   ID: THotkeyID;
 65 | begin
 66 |   for ID := Low(THotkeyID) to High(THotkeyID) do
 67 |     UnregisterHotkey(ID);
 68 |   inherited;
 69 | end;
 70 | 
 71 | function THotkeyService.ParseHotkey(const AHotkeyStr: string; out AModifiers, AKey: UINT): Boolean;
 72 | var
 73 |   Parts: TStringDynArray;
 74 |   Part, PartText: string;
 75 | begin
 76 |   Result := False;
 77 |   AModifiers := 0;
 78 |   AKey := 0;
 79 |   
 80 |   Parts := AHotkeyStr.Split(['+']);
 81 |   if Length(Parts) = 0 then Exit;
 82 |   
 83 |   for Part in Parts do
 84 |   begin
 85 |     PartText := Trim(Part);
 86 |     if SameText(PartText, 'Ctrl') or SameText(PartText, 'Control') then
 87 |       AModifiers := AModifiers or MOD_CONTROL
 88 |     else if SameText(PartText, 'Alt') then
 89 |       AModifiers := AModifiers or MOD_ALT
 90 |     else if SameText(PartText, 'Shift') then
 91 |       AModifiers := AModifiers or MOD_SHIFT
 92 |     else if SameText(PartText, 'Win') or SameText(PartText, 'Windows') then
 93 |       AModifiers := AModifiers or MOD_WIN
 94 |     else
 95 |     begin
 96 |       if Length(PartText) = 1 then
 97 |         AKey := Ord(UpCase(PartText[1]))
 98 |       else if SameText(PartText, 'F1') then AKey := VK_F1
 99 |       else if SameText(PartText, 'F2') then AKey := VK_F2
100 |       else if SameText(PartText, 'F3') then AKey := VK_F3
101 |       else if SameText(PartText, 'F4') then AKey := VK_F4
102 |       else if SameText(PartText, 'F5') then AKey := VK_F5
103 |       else if SameText(PartText, 'F6') then AKey := VK_F6
104 |       else if SameText(PartText, 'F7') then AKey := VK_F7
105 |       else if SameText(PartText, 'F8') then AKey := VK_F8
106 |       else if SameText(PartText, 'F9') then AKey := VK_F9
107 |       else if SameText(PartText, 'F10') then AKey := VK_F10
108 |       else if SameText(PartText, 'F11') then AKey := VK_F11
109 |       else if SameText(PartText, 'F12') then AKey := VK_F12
110 |       else if SameText(PartText, 'Space') then AKey := VK_SPACE
111 |       else if SameText(PartText, 'Enter') then AKey := VK_RETURN
112 |       else if SameText(PartText, 'Esc') or SameText(PartText, 'Escape') then AKey := VK_ESCAPE
113 |       else if SameText(PartText, 'Tab') then AKey := VK_TAB
114 |       else if SameText(PartText, 'Del') or SameText(PartText, 'Delete') then AKey := VK_DELETE
115 |       else if SameText(PartText, 'Ins') or SameText(PartText, 'Insert') then AKey := VK_INSERT
116 |       else if SameText(PartText, 'Home') then AKey := VK_HOME
117 |       else if SameText(PartText, 'End') then AKey := VK_END
118 |       else if SameText(PartText, 'PgUp') or SameText(PartText, 'PageUp') then AKey := VK_PRIOR
119 |       else if SameText(PartText, 'PgDn') or SameText(PartText, 'PageDown') then AKey := VK_NEXT
120 |       else if SameText(PartText, 'Left') then AKey := VK_LEFT
121 |       else if SameText(PartText, 'Right') then AKey := VK_RIGHT
122 |       else if SameText(PartText, 'Up') then AKey := VK_UP
123 |       else if SameText(PartText, 'Down') then AKey := VK_DOWN
124 |       else
125 |         Exit;
126 |     end;
127 |   end;
128 |   
129 |   if AKey <> 0 then
130 |     Result := True;
131 | end;
132 | 
133 | function THotkeyService.RegisterHotkey(AID: THotkeyID; const AHotkeyStr: string; AEvent: THotkeyEvent): Boolean;
134 | var
135 |   Modifiers, Key: UINT;
136 |   HotkeyID: Integer;
137 | begin
138 |   Result := False;
139 |   if not ParseHotkey(AHotkeyStr, Modifiers, Key) then Exit;
140 |   
141 |   UnregisterHotkey(AID);
142 |   
143 |   HotkeyID := BASE_HOTKEY_ID + Ord(AID);
144 |   if Winapi.Windows.RegisterHotKey(FHandle, HotkeyID, Modifiers, Key) then
145 |   begin
146 |     FRegistered[AID] := True;
147 |     FHotkeys[AID].Modifiers := Modifiers;
148 |     FHotkeys[AID].Key := Key;
149 |     FHotkeys[AID].Enabled := True;
150 |     FHotkeys[AID].Event := AEvent;
151 |     FHotkeys[AID].HotkeyStr := AHotkeyStr;
152 |     Result := True;
153 |   end;
154 | end;
155 | 
156 | function THotkeyService.UnregisterHotkey(AID: THotkeyID): Boolean;
157 | var
158 |   HotkeyID: Integer;
159 | begin
160 |   Result := False;
161 |   if not FRegistered[AID] then Exit;
162 |   
163 |   HotkeyID := BASE_HOTKEY_ID + Ord(AID);
164 |   if Winapi.Windows.UnregisterHotKey(FHandle, HotkeyID) then
165 |   begin
166 |     FRegistered[AID] := False;
167 |     FHotkeys[AID].Enabled := False;
168 |     Result := True;
169 |   end;
170 | end;
171 | 
172 | procedure THotkeyService.SetHotkey(AID: THotkeyID; const AHotkeyStr: string; AEvent: THotkeyEvent);
173 | begin
174 |   if FHotkeys[AID].Enabled then
175 |     UnregisterHotkey(AID);
176 |   RegisterHotkey(AID, AHotkeyStr, AEvent);
177 | end;
178 | 
179 | procedure THotkeyService.EnableHotkey(AID: THotkeyID; AEnable: Boolean);
180 | begin
181 |   if AEnable and not FHotkeys[AID].Enabled then
182 |     RegisterHotkey(AID, FHotkeys[AID].HotkeyStr, FHotkeys[AID].Event)
183 |   else if not AEnable and FHotkeys[AID].Enabled then
184 |     UnregisterHotkey(AID);
185 | end;
186 | 
187 | procedure THotkeyService.UpdateFromSettings;
188 | begin
189 |   // Will be called with settings object to update hotkeys
190 | end;
191 | 
192 | procedure THotkeyService.WndProc(var Message: TMessage);
193 | var
194 |   ID: THotkeyID;
195 |   HotkeyID: Integer;
196 | begin
197 |   if Message.Msg = HOTKEY_MSG then
198 |   begin
199 |     HotkeyID := Integer(Message.WParam);
200 |     if (HotkeyID >= BASE_HOTKEY_ID) and (HotkeyID <= BASE_HOTKEY_ID + Ord(High(THotkeyID))) then
201 |     begin
202 |       ID := THotkeyID(HotkeyID - BASE_HOTKEY_ID);
203 |       if FHotkeys[ID].Enabled and Assigned(FHotkeys[ID].Event) then
204 |         FHotkeys[ID].Event();
205 |       Message.Result := 0;
206 |     end;
207 |   end
208 |   else
209 |     Message.Result := LRESULT(Winapi.Windows.DefWindowProc(FHandle, Message.Msg, Message.WParam, Message.LParam));
210 | end;
211 | 
212 | end.

 1 | unit uStartupService;
 2 | 
 3 | interface
 4 | 
 5 | uses
 6 |   System.SysUtils, System.Classes, Winapi.Windows,
 7 |   Winapi.ShlObj, Winapi.ActiveX, Winapi.KnownFolders;
