17 | implementation
18 | 
19 | uses
20 |   System.Win.Registry;
21 | 
22 | { TStartupService }
23 | 
24 | class function TStartupService.IsAutoStartEnabled: Boolean;
25 | var
26 |   Reg: TRegistry;
27 | begin
28 |   Result := False;
29 |   Reg := TRegistry.Create(KEY_READ);
30 |   try
31 |     Reg.RootKey := HKEY_CURRENT_USER;
32 |     if Reg.OpenKey('\Software\Microsoft\Windows\CurrentVersion\Run', False) then
33 |       Result := Reg.ValueExists('StickyNotes');
34 |   finally
35 |     Reg.Free;
36 |   end;
37 | end;
38 | 
39 | class procedure TStartupService.SetAutoStart(AEnable: Boolean);
40 | var
41 |   Reg: TRegistry;
42 |   AppPath: string;
43 | begin
44 |   Reg := TRegistry.Create(KEY_WRITE);
45 |   try
46 |     Reg.RootKey := HKEY_CURRENT_USER;
47 |     if Reg.OpenKey('\Software\Microsoft\Windows\CurrentVersion\Run', True) then
48 |     begin
49 |       AppPath := ParamStr(0);
50 |       if AEnable then
51 |         Reg.WriteString('StickyNotes', '"' + AppPath + '"')
52 |       else
53 |         Reg.DeleteValue('StickyNotes');
54 |     end;
55 |   finally
56 |     Reg.Free;
57 |   end;
58 | end;
