60 | class function TStartupService.GetStartupFolder: string;
61 | var
62 |   Path: array[0..MAX_PATH] of Char;
63 | begin
64 |   Result := '';
65 |   if SHGetFolderPath(0, CSIDL_STARTUP, 0, SHGFP_TYPE_CURRENT, @Path[0]) = S_OK then
66 |     Result := Path;
67 | end;
68 | 
69 | end.

  1 | unit uThemeService;
