  3 | interface
  4 | 
  5 | uses
  6 |   System.SysUtils, System.Classes, Vcl.Graphics, Vcl.Themes, Vcl.Styles,
  7 |   uEnums;
  8 | 
  9 | type
 10 |   TThemeService = class
 11 |   private
 12 |     FDarkTheme: Boolean;
 13 |     FNoteColors: array[TNoteColor] of TColor;
 14 |     FNoteColorsDark: array[TNoteColor] of TColor;
 15 |     procedure InitializeColors;
 16 |   public
 17 |     constructor Create;
 18 |     procedure SetDarkTheme(ADark: Boolean);
 19 |     function GetNoteColor(ANoteColor: TNoteColor): TColor;
 20 |     function GetNoteTextColor(ANoteColor: TNoteColor): TColor;
 21 |     function GetBackgroundColor: TColor;
 22 |     function GetTextColor: TColor;
 23 |     function GetBorderColor: TColor;
 24 |     function GetButtonColor: TColor;
 25 |     function GetButtonTextColor: TColor;
 26 |     function GetHighlightColor: TColor;
