 31 | 
 32 | { TThemeService }
 33 | 
 34 | constructor TThemeService.Create;
 35 | begin
 36 |   inherited;
 37 |   InitializeColors;
 38 |   FDarkTheme := False;
 39 | end;
 40 | 
 41 | procedure TThemeService.InitializeColors;
 42 | begin
 43 |   // Light theme colors (standard sticky note colors)
 44 |   FNoteColors[ncYellow] := $0080FFFF;  // BGR: $FFFF80
 45 |   FNoteColors[ncGreen]  := $0080FF80;  // BGR: $80FF80
 46 |   FNoteColors[ncBlue]   := $00FFC080;  // BGR: $80C0FF
 47 |   FNoteColors[ncPink]   := $00C080FF;  // BGR: $FF80C0
 48 |   FNoteColors[ncPurple] := $00FF80FF;  // BGR: $FF80FF
 49 |   FNoteColors[ncOrange] := $0080C0FF;  // BGR: $FFC080
 50 |   FNoteColors[ncWhite]  := $00FFFFFF;
 51 |   FNoteColors[ncGray]   := $00E0E0E0;
 52 | 
 53 |   // Dark theme colors - muted versions
 54 |   FNoteColorsDark[ncYellow] := $00408080;  // Dark yellow
 55 |   FNoteColorsDark[ncGreen]  := $00408040;  // Dark green
 56 |   FNoteColorsDark[ncBlue]   := $00806040;  // Dark blue
 57 |   FNoteColorsDark[ncPink]   := $00804060;  // Dark pink
 58 |   FNoteColorsDark[ncPurple] := $00804080;  // Dark purple
