  1 | unit uJsonStorage;
  2 | 
  3 | interface
  4 | 
  5 | uses
  6 |   System.SysUtils, System.Classes, System.Generics.Collections, System.IOUtils,
  7 |   System.JSON, System.DateUtils, System.Types,
  8 |   uStorage, uNote, uEnums;
  9 | 
 10 | type
 11 |   TJsonStorage = class(TInterfacedObject, INoteStorage)
 12 |   private
 13 |     FBasePath: string;
 14 |     FNotesPath: string;
 15 |     FSettingsPath: string;
 16 |     FNextID: Int64;
 17 |     function GetNoteFileName(AID: Int64): string;
 18 |     procedure EnsureDirectories;
 19 |     function NoteToJson(const ANote: TNote): TJSONObject;
 20 |     function JsonToNote(const AJson: TJSONObject): TNote;
 21 |   public
 22 |     constructor Create(const ABasePath: string);
 23 |     destructor Destroy; override;
 24 |     function SaveNote(const ANote: TNote): Boolean;
 25 |     function DeleteNote(const ANoteID: Int64): Boolean;
 26 |     function LoadAllNotes: TObjectList<TNote>;
 27 |     function GetNextID: Int64;
 28 |     procedure Initialize;
 29 |     procedure Finalize;
 30 |   end;
 31 | 
 32 | implementation
 33 | 
 34 | function DateTimeToISO8601(const ADateTime: TDateTime): string;
 35 | begin
 36 |   Result := FormatDateTime('yyyy-mm-dd"T"hh:nn:ss', ADateTime);
 37 | end;
 38 | 
 39 | { TJsonStorage }
 40 | 
 41 | constructor TJsonStorage.Create(const ABasePath: string);
 42 | begin
 43 |   inherited Create;
 44 |   FBasePath := ABasePath;
 45 |   FNotesPath := TPath.Combine(FBasePath, 'notes');
 46 |   FSettingsPath := TPath.Combine(FBasePath, 'settings.ini');
 47 |   FNextID := 1;
 48 | end;
 49 | 
 50 | destructor TJsonStorage.Destroy;
 51 | begin
 52 |   Finalize;
 53 |   inherited;
 54 | end;
 55 | 
 56 | procedure TJsonStorage.EnsureDirectories;
 57 | begin
 58 |   if not TDirectory.Exists(FBasePath) then
 59 |     TDirectory.CreateDirectory(FBasePath);
 60 |   if not TDirectory.Exists(FNotesPath) then
 61 |     TDirectory.CreateDirectory(FNotesPath);
 62 | end;
 63 | 
 64 | procedure TJsonStorage.Initialize;
 65 | var
 66 |   Files: TStringDynArray;
 67 |   FileName: string;
 68 |   ID: Int64;
 69 | begin
 70 |   EnsureDirectories;
 71 |   FNextID := 1;
 72 |   Files := TDirectory.GetFiles(FNotesPath, '*.json');
 73 |   for FileName in Files do
 74 |   begin
 75 |     ID := StrToInt64Def(TPath.GetFileNameWithoutExtension(FileName), 0);
 76 |     if ID >= FNextID then
 77 |       FNextID := ID + 1;
 78 |   end;
 79 | end;
 80 | 
 81 | procedure TJsonStorage.Finalize;
 82 | begin
 83 |   // Nothing to do for JSON storage
 84 | end;
 85 | 
 86 | function TJsonStorage.GetNoteFileName(AID: Int64): string;
 87 | begin
 88 |   Result := TPath.Combine(FNotesPath, Format('%.10d.json', [AID]));
 89 | end;
 90 | 
 91 | function TJsonStorage.GetNextID: Int64;
 92 | begin
 93 |   Result := FNextID;
 94 |   Inc(FNextID);
 95 | end;
 96 | 
 97 | function TJsonStorage.NoteToJson(const ANote: TNote): TJSONObject;
 98 | begin
 99 |   Result := TJSONObject.Create;
100 |   Result.AddPair('ID', TJSONNumber.Create(ANote.ID));
101 |   Result.AddPair('Title', ANote.Title);
102 |   Result.AddPair('Content', ANote.Content);
103 |   Result.AddPair('Color', Ord(ANote.Color));
104 |   Result.AddPair('Left', ANote.Left);
105 |   Result.AddPair('Top', ANote.Top);
106 |   Result.AddPair('Width', ANote.Width);
107 |   Result.AddPair('Height', ANote.Height);
108 |   Result.AddPair('AlwaysOnTop', ANote.AlwaysOnTop);
109 |   Result.AddPair('Collapsed', ANote.Collapsed);
110 |   Result.AddPair('Locked', ANote.Locked);
111 |   Result.AddPair('CreatedAt', DateTimeToISO8601(ANote.CreatedAt));
112 |   Result.AddPair('UpdatedAt', DateTimeToISO8601(ANote.UpdatedAt));
113 | end;
114 | 
115 | function TJsonStorage.JsonToNote(const AJson: TJSONObject): TNote;
116 | var
117 |   Note: TNote;
118 |   ColorInt: Integer;
119 |   CreatedStr, UpdatedStr: string;
120 |   Val: TJSONValue;
121 | begin
122 |   if AJson = nil then
123 |     raise Exception.Create('JsonToNote: AJson is nil');
124 |     
125 |   Note := TNote.Create;
126 |   try
127 |     Val := AJson.GetValue('ID');
128 |     if (Val <> nil) and (Val is TJSONNumber) then
129 |       Note.ID := (Val as TJSONNumber).AsInt64
130 |     else
131 |       Note.ID := 0;
132 |       
133 |     Val := AJson.GetValue('Title');
134 |     if (Val <> nil) then
135 |       Note.Title := Val.Value
136 |     else
137 |       Note.Title := '';
138 |       
139 |     Val := AJson.GetValue('Content');
140 |     if (Val <> nil) then
141 |       Note.Content := Val.Value
142 |     else
143 |       Note.Content := '';
144 |       
145 |     Val := AJson.GetValue('Color');
146 |     if (Val <> nil) and (Val is TJSONNumber) then
147 |       ColorInt := (Val as TJSONNumber).AsInt
148 |     else
149 |       ColorInt := Ord(ncYellow);
150 |     Note.Color := TNoteColor(ColorInt);
151 |     
152 |     Val := AJson.GetValue('Left');
153 |     if (Val <> nil) and (Val is TJSONNumber) then
154 |       Note.Left := (Val as TJSONNumber).AsInt
155 |     else
156 |       Note.Left := 100;
157 |       
158 |     Val := AJson.GetValue('Top');
159 |     if (Val <> nil) and (Val is TJSONNumber) then
160 |       Note.Top := (Val as TJSONNumber).AsInt
161 |     else
162 |       Note.Top := 100;
163 |       
164 |     Val := AJson.GetValue('Width');
165 |     if (Val <> nil) and (Val is TJSONNumber) then
166 |       Note.Width := (Val as TJSONNumber).AsInt
167 |     else
168 |       Note.Width := 300;
169 |       
170 |     Val := AJson.GetValue('Height');
171 |     if (Val <> nil) and (Val is TJSONNumber) then
172 |       Note.Height := (Val as TJSONNumber).AsInt
173 |     else
174 |       Note.Height := 250;
175 |       
176 |     Val := AJson.GetValue('AlwaysOnTop');
177 |     if (Val <> nil) and (Val is TJSONTrue) then
178 |       Note.AlwaysOnTop := True
179 |     else if (Val <> nil) and (Val is TJSONFalse) then
180 |       Note.AlwaysOnTop := False
181 |     else
182 |       Note.AlwaysOnTop := False;
183 |       
184 |     Val := AJson.GetValue('Collapsed');
185 |     if (Val <> nil) and (Val is TJSONTrue) then
186 |       Note.Collapsed := True
187 |     else if (Val <> nil) and (Val is TJSONFalse) then
188 |       Note.Collapsed := False
189 |     else
190 |       Note.Collapsed := False;
191 |       
192 |     Val := AJson.GetValue('Locked');
193 |     if (Val <> nil) and (Val is TJSONTrue) then
194 |       Note.Locked := True
195 |     else if (Val <> nil) and (Val is TJSONFalse) then
196 |       Note.Locked := False
197 |     else
198 |       Note.Locked := False;
199 |       
200 |     Val := AJson.GetValue('CreatedAt');
201 |     CreatedStr := '';
202 |     if (Val <> nil) then
203 |       CreatedStr := Val.Value;
204 |     if CreatedStr <> '' then
205 |       Note.CreatedAt := System.DateUtils.ISO8601ToDate(CreatedStr)
206 |     else
207 |       Note.CreatedAt := Now;
208 |       
209 |     Val := AJson.GetValue('UpdatedAt');
210 |     UpdatedStr := '';
211 |     if (Val <> nil) then
212 |       UpdatedStr := Val.Value;
213 |     if UpdatedStr <> '' then
214 |       Note.UpdatedAt := System.DateUtils.ISO8601ToDate(UpdatedStr)
215 |     else
216 |       Note.UpdatedAt := Now;
217 |       
218 |     Result := Note;
219 |   except
220 |     Note.Free;
221 |     raise;
222 |   end;
223 | end;
224 | 
225 | function TJsonStorage.SaveNote(const ANote: TNote): Boolean;
226 | var
227 |   Json: TJSONObject;
228 |   FileName: string;
229 |   Stream: TFileStream;
230 |   Writer: TStreamWriter;
231 | begin
232 |   Result := False;
233 |   try
234 |     EnsureDirectories;
235 |     Json := NoteToJson(ANote);
236 |     try
237 |       FileName := GetNoteFileName(ANote.ID);
238 |       Stream := TFileStream.Create(FileName, fmCreate or fmShareDenyWrite);
239 |       try
240 |         Writer := TStreamWriter.Create(Stream, TEncoding.UTF8);
241 |         try
242 |           Writer.Write(Json.Format);
243 |           Result := True;
244 |         finally
245 |           Writer.Free;
246 |         end;
247 |       finally
248 |         Stream.Free;
249 |       end;
250 |     finally
251 |       Json.Free;
252 |     end;
253 |   except
254 |     on E: Exception do
255 |       Result := False;
256 |   end;
257 | end;
258 | 
259 | function TJsonStorage.DeleteNote(const ANoteID: Int64): Boolean;
260 | var
261 |   FileName: string;
262 | begin
263 |   Result := False;
264 |   try
265 |     FileName := GetNoteFileName(ANoteID);
266 |     if TFile.Exists(FileName) then
267 |     begin
268 |       TFile.Delete(FileName);
269 |       Result := True;
270 |     end;
271 |   except
272 |     Result := False;
273 |   end;
274 | end;
275 | 
276 | function TJsonStorage.LoadAllNotes: TObjectList<TNote>;
277 | var
278 |   Files: TStringDynArray;
279 |   FileName: string;
280 |   JsonText: string;
281 |   Json: TJSONObject;
282 |   Note: TNote;
283 | begin
284 |   Result := TObjectList<TNote>.Create(True);
285 |   try
286 |     EnsureDirectories;
287 |     Files := TDirectory.GetFiles(FNotesPath, '*.json');
288 |     for FileName in Files do
289 |     begin
290 |       try
291 |         JsonText := TFile.ReadAllText(FileName, TEncoding.UTF8);
292 |         Json := TJSONObject.ParseJSONValue(JsonText) as TJSONObject;
293 |         if Json <> nil then
294 |         try
295 |           Note := JsonToNote(Json);
296 |           Result.Add(Note);
297 |         finally
298 |           Json.Free;
299 |         end;
300 |       except
301 |         // Skip corrupted files
302 |       end;
303 |     end;
304 |   except
305 |     Result.Free;
306 |     raise;
307 |   end;
308 | end;
309 | 
310 | end.

