  1 | unit uColorUtils;
  2 | 
  3 | interface
  4 | 
  5 | uses
  6 |   Winapi.Windows, Vcl.Graphics, System.SysUtils, System.Math,
  7 |   uEnums;
  8 | 
  9 | type
 10 |   TColorUtils = class
 11 |   public
 12 |     class function LightenColor(AColor: TColor; AAmount: Integer): TColor;
 13 |     class function DarkenColor(AColor: TColor; AAmount: Integer): TColor;
 14 |     class function GetContrastColor(ABackground: TColor): TColor;
 15 |     class function ColorToHex(AColor: TColor): string;
 16 |     class function HexToColor(const AHex: string): TColor;
 17 |     class function BlendColors(AColor1, AColor2: TColor; AAlpha: Single): TColor;
 18 |     class function IsDarkColor(AColor: TColor): Boolean;
 19 |     class function AdjustBrightness(AColor: TColor; APercent: Integer): TColor;
 20 |     class function GetComplementaryColor(AColor: TColor): TColor;
 21 |   end;
 22 | 
 23 | implementation
 24 | 
 25 | { TColorUtils }
 26 | 
 27 | class function TColorUtils.LightenColor(AColor: TColor; AAmount: Integer): TColor;
 28 | var
 29 |   R, G, B: Byte;
 30 | begin
 31 |   R := GetRValue(AColor);
 32 |   G := GetGValue(AColor);
 33 |   B := GetBValue(AColor);
 34 |   
 35 |   R := Min(255, R + AAmount);
 36 |   G := Min(255, G + AAmount);
 37 |   B := Min(255, B + AAmount);
 38 |   
 39 |   Result := RGB(R, G, B);
 40 | end;
 41 | 
 42 | class function TColorUtils.DarkenColor(AColor: TColor; AAmount: Integer): TColor;
 43 | var
 44 |   R, G, B: Byte;
 45 | begin
 46 |   R := GetRValue(AColor);
 47 |   G := GetGValue(AColor);
 48 |   B := GetBValue(AColor);
 49 |   
 50 |   R := Max(0, R - AAmount);
 51 |   G := Max(0, G - AAmount);
 52 |   B := Max(0, B - AAmount);
 53 |   
 54 |   Result := RGB(R, G, B);
 55 | end;
 56 | 
 57 | class function TColorUtils.GetContrastColor(ABackground: TColor): TColor;
 58 | var
 59 |   Luminance: Double;
 60 |   R, G, B: Byte;
 61 | begin
 62 |   R := GetRValue(ABackground);
 63 |   G := GetGValue(ABackground);
 64 |   B := GetBValue(ABackground);
 65 |   
 66 |   // Calculate relative luminance (WCAG formula)
 67 |   Luminance := (0.299 * R + 0.587 * G + 0.114 * B) / 255;
 68 |   
 69 |   if Luminance > 0.5 then
 70 |     Result := clBlack
 71 |   else
 72 |     Result := clWhite;
 73 | end;
 74 | 
 75 | class function TColorUtils.ColorToHex(AColor: TColor): string;
 76 | begin
 77 |   Result := Format('#%.2x%.2x%.2x', [GetRValue(AColor), GetGValue(AColor), GetBValue(AColor)]);
 78 | end;
 79 | 
 80 | class function TColorUtils.HexToColor(const AHex: string): TColor;
 81 | var
 82 |   Hex: string;
 83 |   R, G, B: Integer;
 84 | begin
 85 |   Result := clWhite;
 86 |   Hex := AHex;
 87 |   
 88 |   if Hex.StartsWith('#') then
 89 |     Hex := Hex.Substring(1);
 90 |   
 91 |   if Length(Hex) = 6 then
 92 |   begin
 93 |     try
 94 |       R := StrToInt('$' + Hex.Substring(0, 2));
 95 |       G := StrToInt('$' + Hex.Substring(2, 2));
 96 |       B := StrToInt('$' + Hex.Substring(4, 2));
 97 |       Result := RGB(R, G, B);
 98 |     except
 99 |       Result := clWhite;
100 |     end;
101 |   end;
102 | end;
103 | 
104 | class function TColorUtils.BlendColors(AColor1, AColor2: TColor; AAlpha: Single): TColor;
105 | var
106 |   R1, G1, B1: Byte;
107 |   R2, G2, B2: Byte;
108 |   R, G, B: Byte;
109 | begin
110 |   R1 := GetRValue(AColor1);
111 |   G1 := GetGValue(AColor1);
112 |   B1 := GetBValue(AColor1);
113 |   
114 |   R2 := GetRValue(AColor2);
115 |   G2 := GetGValue(AColor2);
116 |   B2 := GetBValue(AColor2);
117 |   
118 |   R := Round(R1 * (1 - AAlpha) + R2 * AAlpha);
119 |   G := Round(G1 * (1 - AAlpha) + G2 * AAlpha);
120 |   B := Round(B1 * (1 - AAlpha) + B2 * AAlpha);
121 |   
122 |   Result := RGB(R, G, B);
123 | end;
124 | 
125 | class function TColorUtils.IsDarkColor(AColor: TColor): Boolean;
126 | var
127 |   Luminance: Double;
128 |   R, G, B: Byte;
129 | begin
130 |   R := GetRValue(AColor);
131 |   G := GetGValue(AColor);
132 |   B := GetBValue(AColor);
133 |   
134 |   Luminance := (0.299 * R + 0.587 * G + 0.114 * B) / 255;
135 |   Result := Luminance < 0.5;
136 | end;
137 | 
138 | class function TColorUtils.AdjustBrightness(AColor: TColor; APercent: Integer): TColor;
139 | var
140 |   R, G, B: Byte;
141 |   Factor: Double;
142 | begin
143 |   R := GetRValue(AColor);
144 |   G := GetGValue(AColor);
145 |   B := GetBValue(AColor);
146 |   
147 |   Factor := 1 + (APercent / 100.0);
148 |   
149 |   R := Min(255, Max(0, Round(R * Factor)));
150 |   G := Min(255, Max(0, Round(G * Factor)));
151 |   B := Min(255, Max(0, Round(B * Factor)));
152 |   
153 |   Result := RGB(R, G, B);
154 | end;
155 | 
156 | class function TColorUtils.GetComplementaryColor(AColor: TColor): TColor;
157 | var
158 |   R, G, B: Byte;
159 | begin
160 |   R := GetRValue(AColor);
161 |   G := GetGValue(AColor);
162 |   B := GetBValue(AColor);
163 |   
164 |   Result := RGB(255 - R, 255 - G, 255 - B);
165 | end;
166 | 
167 | end.

