 41 | class procedure TWindowUtils.EnableBorderlessWindow(AForm: TForm);
 42 | begin
 43 |   AForm.BorderStyle := bsNone;
 44 |   AForm.DoubleBuffered := True;
 45 |   AForm.AlphaBlend := False;
 46 |   AForm.KeyPreview := True;
 47 |   AForm.Position := poDesigned;
 48 | end;
