 60 | class procedure TWindowUtils.HandleNCHitTest(AForm: TForm; var Message: TWMNCHitTest);
 61 | var
 62 |   ClientPoint: TPoint;
 63 |   HitTest: Integer;
 64 |   CaptionRect: TRect;
 65 |   LeftBorder, RightBorder, TopBorder, BottomBorder: Boolean;
 66 | begin
 67 |   ClientPoint := AForm.ScreenToClient(Point(Message.XPos, Message.YPos));
 68 |   
 69 |   // Check if in caption area (top area for dragging).
 70 |   // NOTE: the note header has its own real buttons (close/color/pin/collapse/
 71 |   // lock) drawn as child controls, which intercept their own clicks before
 72 |   // WM_NCHITTEST for the parent form is ever consulted. Treating this whole
 73 |   // strip as HTCAPTION (rather than carving out HTCLOSE/HTMINBUTTON zones
 74 |   // that don't line up with the actual button positions) avoids clicks in
 75 |   // the gaps between buttons being misread as a system close/minimize.
 76 |   CaptionRect := Rect(0, 0, AForm.ClientWidth, CAPTION_HEIGHT);
 77 |   if PtInRect(CaptionRect, ClientPoint) then
 78 |     HitTest := HTCAPTION
 79 |   else
 80 |   begin
 81 |     // Check resize borders
 82 |     LeftBorder := ClientPoint.X < RESIZE_BORDER;
 83 |     RightBorder := ClientPoint.X > AForm.ClientWidth - RESIZE_BORDER;
 84 |     TopBorder := ClientPoint.Y < RESIZE_BORDER;
 85 |     BottomBorder := ClientPoint.Y > AForm.ClientHeight - RESIZE_BORDER;
 86 |     
 87 |     if TopBorder and LeftBorder then
 88 |       HitTest := HTTOPLEFT
 89 |     else if TopBorder and RightBorder then
 90 |       HitTest := HTTOPRIGHT
 91 |     else if BottomBorder and LeftBorder then
 92 |       HitTest := HTBOTTOMLEFT
 93 |     else if BottomBorder and RightBorder then
 94 |       HitTest := HTBOTTOMRIGHT
 95 |     else if LeftBorder then
 96 |       HitTest := HTLEFT
 97 |     else if RightBorder then
 98 |       HitTest := HTRIGHT
 99 |     else if TopBorder then
100 |       HitTest := HTTOP
101 |     else if BottomBorder then
102 |       HitTest := HTBOTTOM
103 |     else
104 |       HitTest := HTCLIENT;
105 |   end;
106 |   
107 |   Message.Result := HitTest;
108 | end;
109 | 
110 | class procedure TWindowUtils.HandleNCCalcSize(AForm: TForm; var Message: TWMNCCalcSize);
111 | begin
112 |   // No custom non-client area calculation needed for borderless
113 |   // Windows handles it automatically when we return HT* from NCHitTest
114 | end;
115 | 
116 | class procedure TWindowUtils.HandleNCPaint(AForm: TForm; var Message: TWMNCPaint);
117 | var
118 |   DC: HDC;
119 |   R: TRect;
120 |   Brush: HBRUSH;
121 |   Color: TColor;
122 | begin
123 |   // Paint custom border for borderless window
124 |   DC := GetWindowDC(AForm.Handle);
125 |   try
126 |     GetWindowRect(AForm.Handle, R);
127 |     OffsetRect(R, -R.Left, -R.Top);
128 |     
129 |     if AForm.Brush.Style <> bsClear then
130 |       Color := AForm.Brush.Color
131 |     else
132 |       Color := clWindow;
133 |     
134 |     Brush := CreateSolidBrush(ColorToRGB(Color));
135 |     try
136 |       FrameRect(DC, R, Brush);
137 |     finally
138 |       DeleteObject(Brush);
139 |     end;
140 |   finally
141 |     ReleaseDC(AForm.Handle, DC);
142 |   end;
143 | end;
