147 | constructor TWindowDragHelper.Create(AForm: TForm);
148 | begin
149 |   inherited Create;
150 |   FForm := AForm;
151 |   FDragMode := False;
152 |   FForm.OnMouseDown := MouseDown;
153 |   FForm.OnMouseMove := MouseMove;
154 |   FForm.OnMouseUp := MouseUp;
155 | end;
156 | 
157 | destructor TWindowDragHelper.Destroy;
158 | begin
159 |   FForm.OnMouseDown := nil;
160 |   FForm.OnMouseMove := nil;
161 |   FForm.OnMouseUp := nil;
162 |   inherited;
163 | end;
164 | 
165 | procedure TWindowDragHelper.MouseDown(Sender: TObject; Button: TMouseButton; Shift: TShiftState; X, Y: Integer);
166 | begin
167 |   if (Button = mbLeft) and (Y < CAPTION_HEIGHT) then
168 |   begin
169 |     FDragMode := True;
170 |     FDragOffset := Point(X, Y);
171 |   end;
172 | end;
173 | 
174 | procedure TWindowDragHelper.MouseMove(Sender: TObject; Shift: TShiftState; X, Y: Integer);
175 | begin
176 |   if FDragMode and (ssLeft in Shift) then
177 |   begin
178 |     FForm.Left := FForm.Left + (X - FDragOffset.X);
179 |     FForm.Top := FForm.Top + (Y - FDragOffset.Y);
180 |   end;
181 | end;
182 | 
183 | procedure TWindowDragHelper.MouseUp(Sender: TObject; Button: TMouseButton; Shift: TShiftState; X, Y: Integer);
184 | begin
185 |   FDragMode := False;
186 | end;
187 | 
188 | end.

  1 | unit uMonitorUtils;
  2 | 
  3 | interface
  4 | 
  5 | uses
  6 |   Winapi.Windows, System.SysUtils, System.Types, Vcl.Forms;
  7 | 
  8 | type
  9 |   TMonitorUtils = class
 10 |   public
 11 |     class function GetMonitorFromWindow(AHandle: HWND): HMONITOR;
 12 |     class function GetMonitorRect(AMonitor: HMONITOR): TRect;
 13 |     class function GetMonitorWorkArea(AMonitor: HMONITOR): TRect;
 14 |     class function GetMonitorCount: Integer;
 15 |     class function GetPrimaryMonitor: HMONITOR;
 16 |     class function GetMonitorInfo(AMonitor: HMONITOR; out AInfo: TMonitorInfo): Boolean;
 17 |     class procedure ConstrainToMonitor(var ARect: TRect; AMonitor: HMONITOR = 0; AUseWorkArea: Boolean = True);
 18 |     class function GetMonitorAtPoint(const APoint: TPoint): HMONITOR;
 19 |     class function GetMonitorAtRect(const ARect: TRect): HMONITOR;
 20 |     class procedure CenterRectOnMonitor(var ARect: TRect; AMonitor: HMONITOR = 0);
 21 |     class function IsRectOnScreen(const ARect: TRect): Boolean;
 22 |     class function GetNearestMonitor(const ARect: TRect): HMONITOR;
 23 |   end;
 24 | 
 25 | implementation
 26 | 
 27 | { TMonitorUtils }
 28 | 
 29 | class function TMonitorUtils.GetMonitorFromWindow(AHandle: HWND): HMONITOR;
 30 | begin
 31 |   Result := MonitorFromWindow(AHandle, MONITOR_DEFAULTTONEAREST);
 32 | end;
 33 | 
 34 | class function TMonitorUtils.GetMonitorRect(AMonitor: HMONITOR): TRect;
 35 | var
 36 |   MI: TMonitorInfo;
 37 | begin
 38 |   if GetMonitorInfo(AMonitor, MI) then
 39 |     Result := MI.rcMonitor
 40 |   else
 41 |     Result := Rect(0, 0, Screen.Width, Screen.Height);
 42 | end;
 43 | 
 44 | class function TMonitorUtils.GetMonitorWorkArea(AMonitor: HMONITOR): TRect;
 45 | var
 46 |   MI: TMonitorInfo;
 47 | begin
 48 |   if GetMonitorInfo(AMonitor, MI) then
 49 |     Result := MI.rcWork
 50 |   else
 51 |     Result := Rect(0, 0, Screen.Width, Screen.Height);
 52 | end;
 53 | 
 54 | class function TMonitorUtils.GetMonitorCount: Integer;
 55 | begin
 56 |   Result := Screen.MonitorCount;
 57 | end;
 58 | 
 59 | class function TMonitorUtils.GetPrimaryMonitor: HMONITOR;
 60 | begin
 61 |   Result := MonitorFromPoint(Point(0, 0), MONITOR_DEFAULTTOPRIMARY);
 62 | end;
 63 | 
 64 | class function TMonitorUtils.GetMonitorInfo(AMonitor: HMONITOR; out AInfo: TMonitorInfo): Boolean;
 65 | begin
 66 |   AInfo.cbSize := SizeOf(TMonitorInfo);
 67 |   Result := GetMonitorInfo(AMonitor, @AInfo);
 68 | end;
 69 | 
 70 | class procedure TMonitorUtils.ConstrainToMonitor(var ARect: TRect; AMonitor: HMONITOR; AUseWorkArea: Boolean);
 71 | var
 72 |   MonitorRect: TRect;
 73 |   Width, Height: Integer;
 74 | begin
 75 |   if AMonitor = 0 then
 76 |     AMonitor := GetMonitorFromWindow(0);
 77 |   
 78 |   if AUseWorkArea then
 79 |     MonitorRect := GetMonitorWorkArea(AMonitor)
 80 |   else
 81 |     MonitorRect := GetMonitorRect(AMonitor);
 82 |   
 83 |   Width := ARect.Width;
 84 |   Height := ARect.Height;
 85 |   
 86 |   // Constrain left
 87 |   if ARect.Left < MonitorRect.Left then
 88 |     ARect.Left := MonitorRect.Left;
 89 |   if ARect.Right > MonitorRect.Right then
 90 |     ARect.Left := MonitorRect.Right - Width;
 91 |   
 92 |   // Constrain top
 93 |   if ARect.Top < MonitorRect.Top then
 94 |     ARect.Top := MonitorRect.Top;
 95 |   if ARect.Bottom > MonitorRect.Bottom then
 96 |     ARect.Top := MonitorRect.Bottom - Height;
 97 |   
 98 |   ARect.Right := ARect.Left + Width;
 99 |   ARect.Bottom := ARect.Top + Height;
100 | end;
101 | 
102 | class function TMonitorUtils.GetMonitorAtPoint(const APoint: TPoint): HMONITOR;
103 | begin
104 |   Result := MonitorFromPoint(APoint, MONITOR_DEFAULTTONEAREST);
105 | end;
106 | 
107 | class function TMonitorUtils.GetMonitorAtRect(const ARect: TRect): HMONITOR;
108 | begin
109 |   Result := MonitorFromRect(ARect, MONITOR_DEFAULTTONEAREST);
110 | end;
111 | 
112 | class procedure TMonitorUtils.CenterRectOnMonitor(var ARect: TRect; AMonitor: HMONITOR);
113 | var
114 |   MonitorRect: TRect;
115 |   Width, Height: Integer;
116 | begin
117 |   if AMonitor = 0 then
118 |     AMonitor := GetPrimaryMonitor;
119 |   
120 |   MonitorRect := GetMonitorWorkArea(AMonitor);
121 |   Width := ARect.Width;
122 |   Height := ARect.Height;
123 |   
124 |   ARect.Left := MonitorRect.Left + (MonitorRect.Width - Width) div 2;
125 |   ARect.Top := MonitorRect.Top + (MonitorRect.Height - Height) div 2;
126 |   ARect.Right := ARect.Left + Width;
127 |   ARect.Bottom := ARect.Top + Height;
128 | end;
129 | 
130 | class function TMonitorUtils.IsRectOnScreen(const ARect: TRect): Boolean;
131 | var
132 |   I: Integer;
133 |   MonitorRect: TRect;
134 | begin
135 |   Result := False;
136 |   for I := 0 to Screen.MonitorCount - 1 do
137 |   begin
138 |     MonitorRect := Screen.Monitors[I].BoundsRect;
139 |     if (ARect.Right > MonitorRect.Left) and (ARect.Left < MonitorRect.Right) and
140 |        (ARect.Bottom > MonitorRect.Top) and (ARect.Top < MonitorRect.Bottom) then
141 |       Exit(True);
142 |   end;
143 | end;
144 | 
145 | class function TMonitorUtils.GetNearestMonitor(const ARect: TRect): HMONITOR;
146 | var
147 |   Center: TPoint;
148 | begin
149 |   Center := Point((ARect.Left + ARect.Right) div 2, (ARect.Top + ARect.Bottom) div 2);
150 |   Result := MonitorFromPoint(Center, MONITOR_DEFAULTTONEAREST);
151 | end;
152 | 
153 | end.

