  6 |   System.SysUtils, System.Classes, System.Generics.Collections, System.JSON,
  7 |   System.IOUtils;
  8 | 
  9 | type
 10 |   TJsonUtils = class
 11 |   public
 12 |     class function LoadFromFile(const AFileName: string; out AJson: TJSONObject): Boolean;
 13 |     class function SaveToFile(const AFileName: string; const AJson: TJSONObject): Boolean;
 14 |     class function TryGetString(const AJson: TJSONObject; const APath: string; out AValue: string): Boolean;
 15 |     class function TryGetInteger(const AJson: TJSONObject; const APath: string; out AValue: Integer): Boolean;
 16 |     class function TryGetBoolean(const AJson: TJSONObject; const APath: string; out AValue: Boolean): Boolean;
 17 |     class function TryGetInt64(const AJson: TJSONObject; const APath: string; out AValue: Int64): Boolean;
 18 |     class function TryGetFloat(const AJson: TJSONObject; const APath: string; out AValue: Double): Boolean;
 19 |     class function TryGetObject(const AJson: TJSONObject; const APath: string; out AValue: TJSONObject): Boolean;
 20 |     class function TryGetArray(const AJson: TJSONObject; const APath: string; out AValue: TJSONArray): Boolean;
 21 |     class procedure SetValue(const AJson: TJSONObject; const APath: string; const AValue: string); overload;
 22 |     class procedure SetValue(const AJson: TJSONObject; const APath: string; const AValue: Integer); overload;
 23 |     class procedure SetValue(const AJson: TJSONObject; const APath: string; const AValue: Boolean); overload;
 24 |     class procedure SetValue(const AJson: TJSONObject; const APath: string; const AValue: Int64); overload;
 25 |     class procedure SetValue(const AJson: TJSONObject; const APath: string; const AValue: Double); overload;
 26 |     class function JsonToString(const AJson: TJsonValue; APretty: Boolean = True): string;
 27 |   end;
 28 | 
 29 | implementation
 30 | 
 31 | uses
 32 |   System.Rtti;
 33 | 
 34 | { TJsonUtils }
 35 | 
 36 | class function TJsonUtils.LoadFromFile(const AFileName: string; out AJson: TJSONObject): Boolean;
 37 | var
 38 |   Text: string;
 39 |   Value: TJSONValue;
 40 | begin
 41 |   Result := False;
 42 |   AJson := nil;
 43 |   
 44 |   if not TFile.Exists(AFileName) then Exit;
 45 |   
 46 |   try
 47 |     Text := TFile.ReadAllText(AFileName, TEncoding.UTF8);
 48 |     Value := TJSONObject.ParseJSONValue(Text);
 49 |     if Value is TJSONObject then
 50 |     begin
 51 |       AJson := Value as TJSONObject;
 52 |       Result := True;
 53 |     end
 54 |     else
 55 |       Value.Free;
 56 |   except
 57 |     Result := False;
 58 |   end;
 59 | end;
 60 | 
 61 | class function TJsonUtils.SaveToFile(const AFileName: string; const AJson: TJSONObject): Boolean;
 62 | var
 63 |   Stream: TFileStream;
 64 |   Writer: TStreamWriter;
 65 | begin
 66 |   Result := False;
 67 |   try
 68 |     TDirectory.CreateDirectory(TPath.GetDirectoryName(AFileName));
 69 |     Stream := TFileStream.Create(AFileName, fmCreate or fmShareDenyWrite);
 70 |     try
 71 |       Writer := TStreamWriter.Create(Stream, TEncoding.UTF8);
 72 |       try
 73 |         Writer.Write(AJson.Format);
 74 |         Result := True;
 75 |       finally
 76 |         Writer.Free;
 77 |       end;
 78 |     finally
 79 |       Stream.Free;
 80 |     end;
 81 |   except
 82 |     Result := False;
 83 |   end;
 84 | end;
 85 | 
 86 | class function TJsonUtils.TryGetString(const AJson: TJSONObject; const APath: string; out AValue: string): Boolean;
 87 | var
 88 |   Value: TJSONValue;
 89 | begin
 90 |   Result := False;
 91 |   AValue := '';
 92 |   if AJson = nil then Exit;
 93 |   
 94 |   Value := AJson.GetValue(APath);
 95 |   if (Value <> nil) and (Value.Value <> '') then
 96 |   begin
 97 |     AValue := Value.Value;
 98 |     Result := True;
 99 |   end;
100 | end;
101 | 
102 | class function TJsonUtils.TryGetInteger(const AJson: TJSONObject; const APath: string; out AValue: Integer): Boolean;
103 | var
104 |   Value: TJSONValue;
105 | begin
106 |   Result := False;
107 |   AValue := 0;
108 |   if AJson = nil then Exit;
109 |   
110 |   Value := AJson.GetValue(APath);
111 |   if Value is TJSONNumber then
112 |   begin
113 |     AValue := (Value as TJSONNumber).AsInt;
114 |     Result := True;
115 |   end;
116 | end;
117 | 
118 | class function TJsonUtils.TryGetBoolean(const AJson: TJSONObject; const APath: string; out AValue: Boolean): Boolean;
119 | var
120 |   Value: TJSONValue;
121 | begin
122 |   Result := False;
123 |   AValue := False;
124 |   if AJson = nil then Exit;
125 |   
126 |   Value := AJson.GetValue(APath);
127 |   if Value is TJSONTrue then
128 |   begin
129 |     AValue := True;
130 |     Result := True;
131 |   end
132 |   else if Value is TJSONFalse then
133 |   begin
134 |     AValue := False;
135 |     Result := True;
136 |   end;
137 | end;
138 | 
139 | class function TJsonUtils.TryGetInt64(const AJson: TJSONObject; const APath: string; out AValue: Int64): Boolean;
140 | var
141 |   Value: TJSONValue;
142 | begin
143 |   Result := False;
144 |   AValue := 0;
145 |   if AJson = nil then Exit;
146 |   
147 |   Value := AJson.GetValue(APath);
148 |   if Value is TJSONNumber then
149 |   begin
150 |     AValue := (Value as TJSONNumber).AsInt64;
151 |     Result := True;
152 |   end;
153 | end;
154 | 
155 | class function TJsonUtils.TryGetFloat(const AJson: TJSONObject; const APath: string; out AValue: Double): Boolean;
156 | var
157 |   Value: TJSONValue;
158 | begin
159 |   Result := False;
160 |   AValue := 0;
161 |   if AJson = nil then Exit;
162 |   
163 |   Value := AJson.GetValue(APath);
164 |   if Value is TJSONNumber then
165 |   begin
166 |     AValue := (Value as TJSONNumber).AsDouble;
167 |     Result := True;
168 |   end;
169 | end;
170 | 
171 | class function TJsonUtils.TryGetObject(const AJson: TJSONObject; const APath: string; out AValue: TJSONObject): Boolean;
172 | var
173 |   Value: TJSONValue;
174 | begin
175 |   Result := False;
176 |   AValue := nil;
177 |   if AJson = nil then Exit;
178 |   
179 |   Value := AJson.GetValue(APath);
180 |   if Value is TJSONObject then
181 |   begin
182 |     AValue := Value as TJSONObject;
183 |     Result := True;
184 |   end;
185 | end;
186 | 
187 | class function TJsonUtils.TryGetArray(const AJson: TJSONObject; const APath: string; out AValue: TJSONArray): Boolean;
188 | var
189 |   Value: TJSONValue;
190 | begin
191 |   Result := False;
192 |   AValue := nil;
193 |   if AJson = nil then Exit;
194 |   
195 |   Value := AJson.GetValue(APath);
196 |   if Value is TJSONArray then
197 |   begin
198 |     AValue := Value as TJSONArray;
199 |     Result := True;
200 |   end;
201 | end;
202 | 
203 | class procedure TJsonUtils.SetValue(const AJson: TJSONObject; const APath: string; const AValue: string);
204 | var
205 |   Parts: TStringDynArray;
206 |   Current: TJSONObject;
207 |   I: Integer;
208 |   Parent: TJSONObject;
209 |   Key: string;
210 | begin
211 |   if AJson = nil then Exit;
212 |   Parts := APath.Split(['.']);
213 |   Current := AJson;
214 |   
215 |   for I := 0 to Length(Parts) - 2 do
216 |   begin
217 |     Key := Parts[I];
218 |     if not Current.TryGetValue<TJSONObject>(Key, Parent) then
219 |     begin
220 |       Parent := TJSONObject.Create;
221 |       Current.AddPair(Key, Parent);
222 |     end;
223 |     Current := Parent;
224 |   end;
225 |   
226 |   Key := Parts[High(Parts)];
227 |   Current.RemovePair(Key).Free;
228 |   Current.AddPair(Key, AValue);
229 | end;
230 | 
231 | class procedure TJsonUtils.SetValue(const AJson: TJSONObject; const APath: string; const AValue: Integer);
232 | begin
233 |   SetValue(AJson, APath, AValue.ToString);
234 | end;
235 | 
236 | class procedure TJsonUtils.SetValue(const AJson: TJSONObject; const APath: string; const AValue: Boolean);
237 | begin
238 |   SetValue(AJson, APath, BoolToStr(AValue, True));
239 | end;
240 | 
241 | class procedure TJsonUtils.SetValue(const AJson: TJSONObject; const APath: string; const AValue: Int64);
242 | begin
243 |   SetValue(AJson, APath, AValue.ToString);
244 | end;
245 | 
246 | class procedure TJsonUtils.SetValue(const AJson: TJSONObject; const APath: string; const AValue: Double);
247 | begin
248 |   SetValue(AJson, APath, FloatToStr(AValue));
249 | end;
250 | 
251 | class function TJsonUtils.JsonToString(const AJson: TJsonValue; APretty: Boolean): string;
252 | begin
253 |   if AJson = nil then
254 |     Result := 'null'
255 |   else if APretty then
256 |     Result := AJson.Format
257 |   else
258 |     Result := AJson.ToString;
259 | end;
260 | 
261 | end.
